type RouteOverlayProps = { points: { x: number; y: number }[]; visible: boolean; distance?: number };

export const RouteOverlay_MIN = {"base":[4,4]};

export function RouteOverlay(props: RouteOverlayProps) {
  const { points, visible, distance } = props;
  const uid = useRef("routeoverlay-" + Math.random().toString(36).slice(2)).current;
  const floor = RouteOverlay_MIN.base;

  const pts = Array.isArray(points) ? points.filter((p) => p && isFinite(p.x) && isFinite(p.y)) : [];
  const clamp = (v: number) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const d = useMemo(() => {
    if (pts.length === 0) return "";
    return pts
      .map((p, i) => (i === 0 ? "M " : "L ") + (clamp(p.x) * 1000).toFixed(2) + " " + (clamp(p.y) * 1000).toFixed(2))
      .join(" ");
  }, [JSON.stringify(pts)]);

  const last = pts.length ? pts[pts.length - 1] : null;
  const first = pts.length ? pts[0] : null;

  return (
    <div
      className="h-full w-full relative overflow-hidden transition-all duration-500 ease-out"
      style={{ minWidth: floor[0] + "rem", minHeight: floor[1] + "rem", opacity: visible ? 1 : 0 }}
    >
      <svg
        className="absolute inset-0 h-full w-full"
        viewBox="0 0 1000 1000"
        preserveAspectRatio="none"
      >
        <defs>
          <linearGradient id={uid + "-line"} x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor="#22d3ee" />
            <stop offset="55%" stopColor="#67e8f9" />
            <stop offset="100%" stopColor="#e879f9" />
          </linearGradient>
          <filter id={uid + "-glow"} x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="8" result="b" />
            <feMerge>
              <feMergeNode in="b" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>

        {d ? (
          <g filter={"url(#" + uid + "-glow)"}>
            <path
              d={d}
              fill="none"
              stroke="#0ff"
              strokeOpacity="0.18"
              strokeWidth="14"
              strokeLinejoin="round"
              strokeLinecap="round"
              vectorEffect="non-scaling-stroke"
            />
            <path
              d={d}
              fill="none"
              stroke={"url(#" + uid + "-line)"}
              strokeWidth="3"
              strokeLinejoin="round"
              strokeLinecap="round"
              vectorEffect="non-scaling-stroke"
            />
            <path
              d={d}
              fill="none"
              stroke="#ecfeff"
              strokeWidth="2"
              strokeLinecap="round"
              strokeDasharray="10 26"
              vectorEffect="non-scaling-stroke"
            >
              <animate attributeName="stroke-dashoffset" from="72" to="0" dur="1.6s" repeatCount="indefinite" />
            </path>
          </g>
        ) : null}
      </svg>

      {/* nodes in overlay coordinates */}
      {pts.map((p, i) => {
        const isFirst = i === 0;
        const isLast = i === pts.length - 1;
        return (
          <div
            key={"node-" + i}
            className="absolute"
            style={{ left: clamp(p.x) * 100 + "%", top: clamp(p.y) * 100 + "%" }}
          >
            <div
              className={
                "absolute -translate-x-1/2 -translate-y-1/2 rotate-45 transition-all duration-200 ease-out " +
                (isLast
                  ? "h-3 w-3 bg-fuchsia-500 shadow-[0_0_12px_rgba(232,121,249,0.8)] animate-pulse"
                  : isFirst
                  ? "h-2.5 w-2.5 bg-cyan-300 shadow-[0_0_10px_rgba(34,211,238,0.8)]"
                  : "h-1.5 w-1.5 bg-cyan-200/80 shadow-[0_0_6px_rgba(34,211,238,0.6)]")
              }
            />
            {(isFirst || isLast) && (
              <div
                className={
                  "absolute -translate-x-1/2 -translate-y-1/2 rounded-full border animate-ping " +
                  (isLast ? "h-5 w-5 border-fuchsia-400/60" : "h-5 w-5 border-cyan-400/50")
                }
              />
            )}
          </div>
        );
      })}

      {typeof distance === "number" && pts.length > 0 && last ? (
        <div
          className="absolute h-5 w-20 -translate-x-1/2 transition-all duration-300 ease-out"
          style={{
            left: clamp(last.x) * 100 + "%",
            top: "calc(" + clamp(last.y) * 100 + "% - 1.6rem)",
          }}
        >
          <div className="absolute inset-0 border border-fuchsia-400/40 bg-black/80 shadow-[0_0_12px_rgba(232,121,249,0.5)]" />
          <div className="absolute inset-y-[14%] inset-x-[6%]">
            <FitText className="font-mono font-bold tracking-widest uppercase text-fuchsia-300" wrap={false}>
              {(distance < 10 ? distance.toFixed(1) : Math.round(distance).toString()) + "M"}
            </FitText>
          </div>
        </div>
      ) : null}

      {pts.length === 0 && visible ? (
        <div className="absolute inset-0 flex items-center justify-center">
          <div className="border border-cyan-400/25 bg-black/60 px-2 py-1 text-[10px] font-medium uppercase tracking-[0.15em] leading-tight text-neutral-400">
            NO ROUTE
          </div>
        </div>
      ) : null}
    </div>
  );
}

type LevelBadgeProps = { level: number; progress?: number };

export const LevelBadge_MIN = {"base":[3,3]};

export function LevelBadge(props: LevelBadgeProps) {
  const uid = useRef("levelbadge-" + Math.random().toString(36).slice(2)).current;
  const floor = LevelBadge_MIN.base;
  const hasProg = typeof props.progress === "number" && isFinite(props.progress as number);
  const p = hasProg ? Math.max(0, Math.min(1, props.progress as number)) : 0;

  const lvl = Math.round(props.level);
  const prevRef = useRef(lvl);
  const [flash, setFlash] = useState(false);
  useEffect(() => {
    if (prevRef.current !== lvl) {
      prevRef.current = lvl;
      setFlash(true);
      const t = setTimeout(() => setFlash(false), 620);
      return () => clearTimeout(t);
    }
  }, [lvl]);

  const hex = (r: number) => {
    let d = "";
    for (let i = 0; i < 6; i++) {
      const a = (Math.PI / 180) * (i * 60 - 90);
      const x = 50 + r * Math.cos(a);
      const y = 50 + r * Math.sin(a);
      d += (i === 0 ? "M" : "L") + x.toFixed(2) + " " + y.toFixed(2) + " ";
    }
    return d + "Z";
  };

  const ticks = [];
  for (let i = 0; i < 24; i++) {
    const a = (Math.PI / 180) * (i * 15 - 90);
    const r1 = 47.5;
    const r2 = i % 6 === 0 ? 42 : 45;
    ticks.push(
      <line
        key={"tk-" + i}
        x1={50 + r1 * Math.cos(a)}
        y1={50 + r1 * Math.sin(a)}
        x2={50 + r2 * Math.cos(a)}
        y2={50 + r2 * Math.sin(a)}
        stroke={i % 6 === 0 ? "rgba(34,211,238,0.55)" : "rgba(34,211,238,0.2)"}
        strokeWidth={i % 6 === 0 ? 2 : 1}
      />
    );
  }

  return (
    <div
      className="relative h-full w-full"
      style={{ minWidth: floor[0] + "rem", minHeight: floor[1] + "rem" }}
    >
      <svg
        viewBox="0 0 100 100"
        preserveAspectRatio="xMidYMid meet"
        className="absolute inset-0 h-full w-full"
      >
        <defs>
          <linearGradient id={uid + "-face"} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="rgba(23,23,23,0.95)" />
            <stop offset="100%" stopColor="rgba(0,0,0,0.95)" />
          </linearGradient>
          <linearGradient id={uid + "-arc"} x1="0" y1="1" x2="1" y2="0">
            <stop offset="0%" stopColor="#22d3ee" />
            <stop offset="100%" stopColor="#a5f3fc" />
          </linearGradient>
          <radialGradient id={uid + "-glow"} cx="50%" cy="50%" r="50%">
            <stop offset="55%" stopColor="rgba(34,211,238,0)" />
            <stop offset="100%" stopColor="rgba(34,211,238,0.22)" />
          </radialGradient>
          <filter id={uid + "-blur"} x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="2.4" />
          </filter>
        </defs>

        <circle cx="50" cy="50" r="49" fill={"url(#" + uid + "-glow)"} />

        <path d={hex(47)} fill={"url(#" + uid + "-face)"} stroke="rgba(34,211,238,0.28)" strokeWidth="1.5" />
        <path d={hex(41)} fill="none" stroke="rgba(34,211,238,0.14)" strokeWidth="1" />
        {ticks}

        {hasProg ? (
          <g>
            <path
              d={hex(44)}
              pathLength={1}
              fill="none"
              stroke="rgba(34,211,238,0.14)"
              strokeWidth="5"
              strokeLinecap="butt"
            />
            <path
              d={hex(44)}
              pathLength={1}
              fill="none"
              stroke={"url(#" + uid + "-arc)"}
              strokeWidth="5"
              strokeLinecap="butt"
              strokeDasharray={p + " 1"}
              filter={"url(#" + uid + "-blur)"}
              opacity="0.8"
              style={{ transition: "stroke-dasharray 600ms cubic-bezier(.2,.8,.2,1)" }}
            />
            <path
              d={hex(44)}
              pathLength={1}
              fill="none"
              stroke={"url(#" + uid + "-arc)"}
              strokeWidth="3"
              strokeLinecap="butt"
              strokeDasharray={p + " 1"}
              style={{ transition: "stroke-dasharray 600ms cubic-bezier(.2,.8,.2,1)" }}
            />
          </g>
        ) : (
          <path d={hex(44)} fill="none" stroke="rgba(34,211,238,0.3)" strokeWidth="1.5" strokeDasharray="3 4" />
        )}

        {flash ? (
          <path d={hex(47)} fill="none" stroke="#e879f9" strokeWidth="3" className="animate-ping" />
        ) : null}
      </svg>

      <div className="absolute inset-[26%] flex items-center justify-center">
        <FitText
          wrap={false}
          className={
            "font-mono font-bold tracking-widest uppercase transition-all duration-200 ease-out " +
            (flash ? "text-fuchsia-300 drop-shadow-[0_0_10px_rgba(232,121,249,0.8)]" : "text-cyan-300 drop-shadow-[0_0_6px_rgba(34,211,238,0.5)]")
          }
        >
          {String(lvl)}
        </FitText>
      </div>
    </div>
  );
}

type TabSelectorProps = { options: { id: string; label: string; count?: number }[]; value: string; onChange: (id: string) => void };

export const TabSelector_MIN = {"base":[8,2.25]};

export function TabSelector(props: TabSelectorProps) {
  const { options, value, onChange } = props;
  const uid = useRef("tabselector-" + Math.random().toString(36).slice(2)).current;
  const [hover, setHover] = useState<string | null>(null);
  const [pressed, setPressed] = useState<string | null>(null);
  const floor = TabSelector_MIN.base;

  return (
    <div
      className="h-full w-full relative"
      style={{ minWidth: floor[0] + "rem", minHeight: floor[1] + "rem" }}
    >
      <div className="absolute inset-0 bg-black/60 ring-1 ring-cyan-400/10 shadow-[inset_0_0_12px_rgba(0,0,0,0.8)]" />
      <div
        className="absolute inset-0 overflow-y-auto overflow-x-hidden [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
      >
        {options.length === 0 ? (
          <div className="h-full w-full flex items-center justify-center">
            <span className="text-[10px] font-medium uppercase tracking-[0.15em] text-neutral-500">
              — — —
            </span>
          </div>
        ) : (
          <div className="min-h-full w-full flex flex-wrap content-stretch items-stretch gap-[2px] p-[2px]">
            {options.map((o, i) => {
              const active = o.id === value;
              const isHover = hover === o.id && !active;
              const isPress = pressed === o.id;
              return (
                <button
                  key={"tab-" + uid + "-" + o.id}
                  type="button"
                  onClick={() => onChange(o.id)}
                  onPointerDown={() => setPressed(o.id)}
                  onPointerUp={() => setPressed(null)}
                  onPointerCancel={() => setPressed(null)}
                  onPointerEnter={() => setHover(o.id)}
                  onPointerLeave={() => { setHover(null); setPressed(null); }}
                  className={
                    "group relative flex-1 basis-[5.5rem] min-w-0 flex items-center justify-center gap-1.5 px-2 overflow-hidden border transition-all duration-200 ease-out focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-300/70 " +
                    (active
                      ? "border-cyan-400/60 bg-cyan-400/10 text-cyan-200 shadow-[0_0_14px_rgba(34,211,238,0.28)] "
                      : "border-cyan-400/15 bg-neutral-900/70 text-cyan-200/60 hover:bg-cyan-400/10 hover:border-cyan-400/40 hover:text-cyan-100 ") +
                    (isPress ? "scale-[0.97] brightness-125 " : "")
                  }
                  style={{
                    clipPath:
                      "polygon(0.45rem 0, 100% 0, 100% calc(100% - 0.45rem), calc(100% - 0.45rem) 100%, 0 100%)",
                    transitionDelay: i * 12 + "ms",
                  }}
                >
                  <span
                    className={
                      "pointer-events-none absolute inset-0 bg-gradient-to-b transition-opacity duration-300 " +
                      (active
                        ? "from-cyan-400/25 via-transparent to-transparent opacity-100"
                        : "from-cyan-300/10 via-transparent to-transparent " + (isHover ? "opacity-100" : "opacity-0"))
                    }
                  />
                  <span
                    className={
                      "pointer-events-none absolute left-0 top-0 h-full w-[2px] transition-all duration-300 ease-out " +
                      (active
                        ? "bg-cyan-300 shadow-[0_0_10px_rgba(34,211,238,0.8)] opacity-100"
                        : isHover
                        ? "bg-cyan-400/50 opacity-100"
                        : "opacity-0")
                    }
                  />
                  <span
                    className={
                      "pointer-events-none absolute bottom-0 left-0 h-[2px] bg-gradient-to-r from-cyan-300 to-fuchsia-400 shadow-[0_0_8px_rgba(34,211,238,0.7)] transition-all duration-300 ease-out " +
                      (active ? "w-full opacity-100" : "w-0 opacity-0")
                    }
                  />
                  {active && (
                    <span className="pointer-events-none absolute right-[0.15rem] top-[0.15rem] h-1 w-1 rounded-full bg-fuchsia-400 shadow-[0_0_8px_rgba(232,121,249,0.8)] animate-pulse" />
                  )}
                  <span
                    className={
                      "relative min-w-0 truncate text-[11px] font-bold uppercase tracking-[0.16em] leading-none transition-all duration-200 " +
                      (active ? "text-cyan-100 drop-shadow-[0_0_6px_rgba(34,211,238,0.6)]" : "")
                    }
                  >
                    {o.label}
                  </span>
                  {typeof o.count === "number" && (
                    <span
                      className={
                        "relative rounded-full border px-1.5 py-[1px] text-[9px] font-semibold leading-none tabular-nums transition-all duration-200 " +
                        (active
                          ? "border-fuchsia-400/60 bg-fuchsia-500/25 text-fuchsia-200 shadow-[0_0_10px_rgba(232,121,249,0.45)]"
                          : "border-cyan-400/25 bg-black/50 text-cyan-200/60")
                      }
                    >
                      {o.count}
                    </span>
                  )}
                </button>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

type ActionButtonProps = { onPress: () => void; disabled?: boolean; tone?: 'neutral' | 'accent' | 'danger'; children?: React.ReactNode };

export const ActionButton_MIN = {"base":[4,2]};

export function ActionButton(props: ActionButtonProps) {
  const tone = props.tone || 'neutral';
  const disabled = !!props.disabled;
  const uid = useRef("actionbutton-" + Math.random().toString(36).slice(2)).current;
  const [pressed, setPressed] = useState(false);
  const [hover, setHover] = useState(false);
  const [flash, setFlash] = useState(0);

  const T = {
    neutral: {
      face: "bg-neutral-800/80",
      glowFace: "rgba(34,211,238,0.10)",
      edge: "rgba(34,211,238,0.45)",
      edgeHot: "rgba(165,243,252,0.95)",
      text: hover && !disabled ? "text-cyan-100" : "text-cyan-300",
      glow: "0 0 16px rgba(34,211,238,0.45)",
      bar: "rgba(34,211,238,0.9)"
    },
    accent: {
      face: "bg-gradient-to-r from-cyan-400 to-cyan-300",
      glowFace: "rgba(255,255,255,0.18)",
      edge: "rgba(103,232,249,0.8)",
      edgeHot: "rgba(255,255,255,0.95)",
      text: "text-black",
      glow: "0 0 22px rgba(34,211,238,0.7)",
      bar: "rgba(0,0,0,0.6)"
    },
    danger: {
      face: "bg-gradient-to-r from-rose-500 to-red-600",
      glowFace: "rgba(255,255,255,0.15)",
      edge: "rgba(251,113,133,0.7)",
      edgeHot: "rgba(255,228,230,0.95)",
      text: "text-white",
      glow: "0 0 18px rgba(244,63,94,0.65)",
      bar: "rgba(255,255,255,0.7)"
    }
  }[tone];

  const fire = () => {
    if (disabled) return;
    setFlash(function (f) { return f + 1; });
    props.onPress();
  };

  return (
    <div
      className="relative h-full w-full select-none"
      style={{ minWidth: ActionButton_MIN.base[0] + "rem", minHeight: ActionButton_MIN.base[1] + "rem" }}
    >
      <button
        type="button"
        disabled={disabled}
        onPointerDown={function (e) {
          if (disabled) return;
          (e.currentTarget as any).setPointerCapture?.(e.pointerId);
          setPressed(true);
        }}
        onPointerUp={function () { if (pressed) { setPressed(false); fire(); } }}
        onPointerCancel={function () { setPressed(false); }}
        onPointerEnter={function () { setHover(true); }}
        onPointerLeave={function () { setHover(false); setPressed(false); }}
        onKeyDown={function (e) { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setPressed(true); } }}
        onKeyUp={function (e) { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setPressed(false); fire(); } }}
        className={
          "group absolute inset-0 touch-none overflow-hidden border-0 bg-transparent p-0 transition-all duration-200 ease-out focus-visible:outline-none " +
          (disabled ? "cursor-not-allowed opacity-40 grayscale" : "cursor-pointer")
        }
        style={{
          transform: pressed && !disabled ? "scale(0.965)" : "scale(1)",
          filter: !disabled && hover ? "brightness(1.18)" : "none",
          clipPath: "polygon(0 0, calc(100% - 0.55rem) 0, 100% 0.55rem, 100% 100%, 0.55rem 100%, 0 calc(100% - 0.55rem))"
        }}
      >
        {/* face */}
        <span
          className={"absolute inset-0 " + T.face + " transition-all duration-200 ease-out"}
          style={{ boxShadow: !disabled && (hover || pressed) ? T.glow : "inset 0 0 14px rgba(0,0,0,0.7)" }}
        />
        {/* scanlines */}
        <span
          className="pointer-events-none absolute inset-0 opacity-[0.18] mix-blend-overlay"
          style={{ backgroundImage: "repeating-linear-gradient(0deg, rgba(255,255,255,0.5) 0px, rgba(255,255,255,0.5) 1px, transparent 1px, transparent 3px)" }}
        />
        {/* diagonal sheen sweep on hover */}
        <span
          className="pointer-events-none absolute inset-y-0 w-1/3 transition-all duration-500 ease-out"
          style={{
            left: !disabled && hover ? "110%" : "-45%",
            background: "linear-gradient(100deg, transparent, " + T.glowFace + ", transparent)",
            transform: "skewX(-18deg)"
          }}
        />
        {/* flash on press */}
        <span
          key={"flash-" + flash}
          className={"pointer-events-none absolute inset-0 " + (flash > 0 ? "animate-[ping_0.45s_ease-out_1]" : "")}
          style={{ background: flash > 0 ? T.glowFace : "transparent", opacity: 0 }}
        />
        {/* border frame */}
        <svg className="pointer-events-none absolute inset-0 h-full w-full" viewBox="0 0 100 100" preserveAspectRatio="none">
          <defs>
            <linearGradient id={uid + "-edge"} x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stopColor={!disabled && (hover || pressed) ? T.edgeHot : T.edge} />
              <stop offset="55%" stopColor={T.edge} />
              <stop offset="100%" stopColor={!disabled && hover ? T.edgeHot : T.edge} />
            </linearGradient>
          </defs>
          <path
            d="M0.8 0.8 H92 L99.2 8 V99.2 H8 L0.8 92 Z"
            fill="none"
            stroke={"url(#" + uid + "-edge)"}
            strokeWidth={pressed ? 2.6 : 1.6}
            vectorEffect="non-scaling-stroke"
            className="transition-all duration-200 ease-out"
          />
        </svg>
        {/* corner ticks */}
        <span className="pointer-events-none absolute left-0 top-0 h-[3px] transition-all duration-300 ease-out" style={{ width: hover && !disabled ? "45%" : "18%", background: T.bar }} />
        <span className="pointer-events-none absolute bottom-0 right-0 h-[3px] transition-all duration-300 ease-out" style={{ width: hover && !disabled ? "45%" : "18%", background: T.bar }} />
        {/* face content */}
        {props.children !== undefined && props.children !== null && props.children !== false ? (
          <span className="absolute inset-x-[10%] inset-y-[18%]">
            <FitText className={"font-mono font-bold uppercase tracking-widest transition-colors duration-200 " + T.text}>
              {props.children}
            </FitText>
          </span>
        ) : null}
      </button>
    </div>
  );
}

type ObjectiveChecklistProps = { steps: { id: string; label: string; done: boolean; optional?: boolean }[]; activeId?: string | null };

export const ObjectiveChecklist_MIN = {"base":[9,5]};

export function ObjectiveChecklist(props: ObjectiveChecklistProps) {
  const uid = useRef("objchk-" + Math.random().toString(36).slice(2)).current;
  const steps = props.steps || [];
  const total = steps.length;
  const doneCount = steps.reduce(function (a, s) { return a + (s.done ? 1 : 0); }, 0);
  const pct = total > 0 ? (doneCount / total) * 100 : 0;
  const floor = ObjectiveChecklist_MIN.base;

  return (
    <div className="h-full w-full flex flex-col" style={{ minWidth: floor[0] + "rem", minHeight: floor[1] + "rem" }}>
      <style>{"@keyframes " + uid + "-scan{0%{transform:translateX(-100%)}100%{transform:translateX(300%)}}@keyframes " + uid + "-blip{0%,100%{opacity:.35;transform:scale(.82)}50%{opacity:1;transform:scale(1.12)}}@keyframes " + uid + "-in{from{opacity:0;transform:translateX(-6px)}to{opacity:1;transform:none}}"}</style>

      {/* progress rail */}
      <div className="relative h-1.5 w-full bg-black/60 border border-cyan-400/20 overflow-hidden">
        <div
          className="absolute inset-y-0 left-0 bg-gradient-to-r from-cyan-400 to-cyan-200 shadow-[0_0_8px_rgba(34,211,238,0.6)] transition-all duration-500 ease-out"
          style={{ width: pct + "%" }}
        />
        {total > 0 && doneCount < total ? (
          <div
            className="absolute inset-y-0 w-1/4 bg-gradient-to-r from-transparent via-cyan-300/25 to-transparent"
            style={{ animation: uid + "-scan 2.4s linear infinite" }}
          />
        ) : null}
      </div>

      {/* list */}
      <div className="relative flex-1 min-h-0 min-w-0 mt-2 overflow-y-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
        {total === 0 ? (
          <div className="h-full w-full flex items-center justify-center">
            <span className="text-[10px] font-medium uppercase tracking-[0.15em] leading-tight text-neutral-500">NO OBJECTIVES</span>
          </div>
        ) : (
          <div className="flex flex-col">
            {steps.map(function (s, i) {
              const active = props.activeId != null && props.activeId === s.id && !s.done;
              const accent = s.done
                ? "text-cyan-300"
                : active
                ? "text-amber-300"
                : s.optional
                ? "text-fuchsia-400"
                : "text-cyan-100/70";
              return (
                <div
                  key={s.id}
                  className={
                    "relative flex items-stretch gap-2 pl-1 pr-1 py-1 transition-all duration-200 ease-out " +
                    (active ? "bg-amber-400/10 border-l-2 border-amber-300 " : "border-l-2 border-transparent ") +
                    (s.done ? "opacity-70 " : "")
                  }
                  style={{ animation: uid + "-in 320ms ease-out both", animationDelay: Math.min(i, 10) * 35 + "ms" }}
                >
                  {/* spine + node */}
                  <div className="relative w-4 flex flex-col items-center">
                    {i > 0 ? (
                      <div className={"absolute top-0 h-1/2 w-px " + (s.done ? "bg-cyan-400/50" : "bg-cyan-400/15")} />
                    ) : null}
                    {i < total - 1 ? (
                      <div className={"absolute bottom-0 h-1/2 w-px " + (s.done ? "bg-cyan-400/40" : "bg-cyan-400/15")} />
                    ) : null}
                    <div className="relative my-auto">
                      <svg viewBox="0 0 24 24" preserveAspectRatio="xMidYMid meet" className="w-4 h-4 overflow-visible">
                        <defs>
                          <linearGradient id={uid + "-fill"} x1="0" y1="0" x2="1" y2="1">
                            <stop offset="0%" stopColor="#22d3ee" />
                            <stop offset="100%" stopColor="#a5f3fc" />
                          </linearGradient>
                        </defs>
                        <rect
                          x="3" y="3" width="18" height="18"
                          fill={s.done ? "url(#" + uid + "-fill)" : "rgba(0,0,0,0.6)"}
                          stroke={s.done ? "#67e8f9" : active ? "#fcd34d" : s.optional ? "rgba(232,121,249,0.6)" : "rgba(34,211,238,0.35)"}
                          strokeWidth="2"
                          style={{
                            transition: "all 300ms ease-out",
                            filter: s.done
                              ? "drop-shadow(0 0 4px rgba(34,211,238,0.7))"
                              : active
                              ? "drop-shadow(0 0 5px rgba(252,211,77,0.6))"
                              : "none",
                            animation: active ? uid + "-blip 1.4s ease-in-out infinite" : undefined,
                          }}
                        />
                        {s.done ? (
                          <path d="M7 12.5l3.2 3.3L17 8.6" fill="none" stroke="#000" strokeWidth="2.6" strokeLinecap="square" />
                        ) : null}
                      </svg>
                    </div>
                  </div>

                  {/* label */}
                  <div className="flex-1 min-w-0 flex items-center gap-1.5">
                    <span
                      className={
                        "min-w-0 truncate text-xs font-mono leading-none tracking-[0.08em] uppercase transition-colors duration-200 " +
                        accent + (s.done ? " line-through decoration-cyan-400/60" : "") + (active ? " font-bold" : " font-semibold")
                      }
                    >
                      {s.label}
                    </span>
                    {s.optional ? (
                      <span className="shrink text-[10px] font-medium uppercase tracking-[0.15em] leading-none text-fuchsia-400/90 border border-fuchsia-400/40 rounded-full px-1.5 py-0.5 bg-neutral-800/70">
                        OPT
                      </span>
                    ) : null}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

type ItemDetailsProps = { item: { id: string; label: string; description?: string; rarity?: string; stats?: { label: string; value: number | string }[] } | null };

const ITEM_DETAILS_RARITY: Record<string, { text: string; border: string; glow: string; bar: string }> = {
  common: { text: "text-neutral-300", border: "border-neutral-500/60", glow: "rgba(163,163,163,0.35)", bar: "from-neutral-400 to-neutral-200" },
  uncommon: { text: "text-emerald-400", border: "border-emerald-400/60", glow: "rgba(52,211,153,0.45)", bar: "from-emerald-400 to-emerald-200" },
  rare: { text: "text-cyan-300", border: "border-cyan-400/60", glow: "rgba(34,211,238,0.5)", bar: "from-cyan-400 to-cyan-200" },
  epic: { text: "text-fuchsia-400", border: "border-fuchsia-400/60", glow: "rgba(232,121,249,0.5)", bar: "from-fuchsia-500 to-purple-300" },
  legendary: { text: "text-amber-300", border: "border-amber-300/60", glow: "rgba(252,211,77,0.5)", bar: "from-amber-400 to-yellow-200" },
};

export const ItemDetails_MIN = {"base":[11,8]};

export function ItemDetails(props: ItemDetailsProps) {
  const uid = useRef("itemdetails-" + Math.random().toString(36).slice(2)).current;
  const item = props.item;
  const rKey = (item && item.rarity ? String(item.rarity).toLowerCase() : "common");
  const r = ITEM_DETAILS_RARITY[rKey] || ITEM_DETAILS_RARITY.common;
  const stats = (item && item.stats) || [];

  const [pulse, setPulse] = useState(0);
  useEffect(() => { setPulse((p) => p + 1); }, [item ? item.id : null]);

  if (!item) {
    return (
      <div className="h-full w-full relative overflow-hidden" style={{ minWidth: ItemDetails_MIN.base[0] + "rem", minHeight: ItemDetails_MIN.base[1] + "rem" }}>
        <div className="absolute inset-0 bg-black/60 border border-cyan-400/20 shadow-[inset_0_0_12px_rgba(0,0,0,0.8)]" />
        <div className="absolute inset-0 opacity-[0.12]" style={{ backgroundImage: "repeating-linear-gradient(135deg,rgba(34,211,238,0.6) 0px,rgba(34,211,238,0.6) 1px,transparent 1px,transparent 7px)" }} />
        <div className="absolute inset-[14%] flex items-center justify-center">
          <FitText className="font-mono font-bold tracking-widest uppercase text-neutral-500">NO ITEM SELECTED</FitText>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full w-full relative overflow-hidden" style={{ minWidth: ItemDetails_MIN.base[0] + "rem", minHeight: ItemDetails_MIN.base[1] + "rem" }}>
      <div className={"absolute inset-0 bg-gradient-to-b from-neutral-900/90 to-black/95 border " + r.border + " transition-all duration-200 ease-out"} style={{ boxShadow: "inset 0 0 18px rgba(0,0,0,0.85), 0 0 18px " + r.glow }} />
      <div className="absolute inset-0 opacity-[0.07] pointer-events-none" style={{ backgroundImage: "repeating-linear-gradient(0deg,rgba(255,255,255,0.7) 0px,rgba(255,255,255,0.7) 1px,transparent 1px,transparent 4px)" }} />
      <div key={"sweep-" + pulse + uid} className="absolute inset-0 pointer-events-none" style={{ backgroundImage: "linear-gradient(100deg,transparent 40%," + r.glow + " 50%,transparent 60%)", animation: "itemdetails-sweep-" + uid + " 700ms ease-out 1" }} />
      <style>{"@keyframes itemdetails-sweep-" + uid + "{from{transform:translateX(-100%)}to{transform:translateX(100%)}}"}</style>

      <div className="absolute inset-0 flex flex-col p-2 gap-2">
        {/* name band */}
        <div className="relative w-full flex-[0_0_28%] min-h-0 flex items-stretch gap-2">
          <div className={"w-[3px] " + (rKey === "common" ? "bg-neutral-400" : rKey === "uncommon" ? "bg-emerald-400" : rKey === "rare" ? "bg-cyan-400" : rKey === "epic" ? "bg-fuchsia-500" : "bg-amber-400")} style={{ boxShadow: "0 0 10px " + r.glow }} />
          <div className="flex-1 min-w-0 min-h-0 flex flex-col">
            <div className="flex-1 min-h-0 min-w-0">
              <FitText className={"font-mono font-bold tracking-widest uppercase " + r.text + " transition-colors duration-200"}>{item.label}</FitText>
            </div>
            {item.rarity ? (
              <div className={"mt-1 text-[10px] font-medium uppercase tracking-[0.15em] leading-tight truncate min-w-0 " + r.text + "/80"}>{item.rarity}</div>
            ) : null}
          </div>
        </div>

        {item.description ? (
          <div className="w-full flex-[0_0_auto] max-h-[30%] overflow-y-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden bg-black/50 ring-1 ring-cyan-400/10 p-2">
            <div className="text-sm font-normal tracking-normal leading-relaxed text-cyan-100/90">{item.description}</div>
          </div>
        ) : null}

        <div className="flex-1 min-h-0 w-full overflow-y-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
          {stats.length === 0 ? (
            <div className="h-full w-full flex items-center justify-start">
              <div className="text-[10px] font-medium uppercase tracking-[0.15em] text-neutral-500 truncate min-w-0">NO STATS</div>
            </div>
          ) : (
            <div className="flex flex-col">
              {stats.map((s, i) => (
                <div key={"st-" + i + "-" + s.label} className="flex items-center gap-2 h-6 border-b border-cyan-400/10 last:border-b-0 hover:bg-cyan-400/10 transition-colors duration-150">
                  <div className="flex-1 min-w-0 truncate text-xs font-semibold uppercase tracking-[0.18em] leading-none text-cyan-300/80">{s.label}</div>
                  <div className={"min-w-0 truncate text-xs font-bold uppercase tracking-[0.18em] leading-none " + r.text}>{String(s.value)}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      <div className="absolute left-0 bottom-0 h-[2px] w-full overflow-hidden">
        <div key={"bar-" + pulse} className={"h-full w-full bg-gradient-to-r " + r.bar} style={{ boxShadow: "0 0 8px " + r.glow }} />
      </div>
    </div>
  );
}

type CharacterPortraitProps = { src: string; alt?: string; status?: 'normal' | 'damaged' | 'critical' };

export const CharacterPortrait_MIN = {"base":[4,5]};

export function CharacterPortrait(props: CharacterPortraitProps) {
  const uid = useRef("cportrait-" + Math.random().toString(36).slice(2)).current;
  const status = props.status || "normal";
  const [loaded, setLoaded] = useState(false);
  const [err, setErr] = useState(false);

  const tone =
    status === "critical"
      ? { ring: "ring-rose-500/50", border: "border-rose-500/60", glow: "shadow-[0_0_22px_rgba(244,63,94,0.45)]", hex: "#f43f5e", tint: "bg-rose-600/25" }
      : status === "damaged"
      ? { ring: "ring-amber-300/40", border: "border-amber-300/50", glow: "shadow-[0_0_18px_rgba(251,191,36,0.35)]", hex: "#fbbf24", tint: "bg-amber-500/15" }
      : { ring: "ring-cyan-400/25", border: "border-cyan-400/40", glow: "shadow-[0_0_18px_rgba(34,211,238,0.25)]", hex: "#22d3ee", tint: "bg-cyan-400/5" };

  const corner = (pts: string, key: string) => (
    <polyline key={key} points={pts} fill="none" stroke={tone.hex} strokeWidth="1.6" strokeLinecap="square" opacity="0.9" />
  );

  return (
    <div
      className="relative h-full w-full"
      style={{ minWidth: CharacterPortrait_MIN.base[0] + "rem", minHeight: CharacterPortrait_MIN.base[1] + "rem" }}
    >
      <style>{"@keyframes " + uid + "-scan{0%{transform:translateY(-110%)}100%{transform:translateY(510%)}}@keyframes " + uid + "-glitch{0%,88%,100%{transform:translate(0,0);opacity:0}90%{transform:translate(-2%,0);opacity:.55}93%{transform:translate(2%,1%);opacity:.4}96%{transform:translate(-1%,-1%);opacity:.5}}@keyframes " + uid + "-pulse{0%,100%{opacity:.25}50%{opacity:.7}}"}</style>

      <div className={"absolute inset-0 overflow-hidden bg-black/60 border " + tone.border + " " + tone.glow + " ring-1 " + tone.ring + " transition-all duration-200 ease-out"}>
        {/* image */}
        <div className="absolute inset-0">
          {!err && props.src ? (
            <img
              src={props.src}
              alt={props.alt || ""}
              draggable={false}
              onLoad={() => setLoaded(true)}
              onError={() => setErr(true)}
              className={
                "h-full w-full object-cover transition-all duration-500 ease-out " +
                (loaded ? "opacity-100 scale-100" : "opacity-0 scale-105") +
                (status === "critical" ? " saturate-150 contrast-125" : status === "damaged" ? " saturate-75" : "")
              }
            />
          ) : (
            <div className="absolute inset-0 bg-gradient-to-br from-neutral-900 via-black to-neutral-900 flex items-center justify-center">
              <svg viewBox="0 0 24 24" preserveAspectRatio="xMidYMid meet" className="h-1/2 w-1/2 opacity-40">
                <circle cx="12" cy="8.5" r="3.6" fill="none" stroke={tone.hex} strokeWidth="1.1" />
                <path d="M4.5 20c1.2-4.2 4.1-6.2 7.5-6.2S18.3 15.8 19.5 20" fill="none" stroke={tone.hex} strokeWidth="1.1" />
              </svg>
            </div>
          )}
        </div>

        {/* status tint */}
        <div className={"absolute inset-0 " + tone.tint + " mix-blend-screen pointer-events-none transition-colors duration-300"} />

        {/* scanlines */}
        <div
          className="absolute inset-0 pointer-events-none opacity-30"
          style={{ backgroundImage: "repeating-linear-gradient(to bottom, rgba(0,0,0,0.55) 0px, rgba(0,0,0,0.55) 1px, transparent 1px, transparent 3px)" }}
        />
        {/* sweep */}
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
          <div
            className="absolute left-0 w-full"
            style={{
              height: "18%",
              background: "linear-gradient(to bottom, transparent, " + tone.hex + "55, transparent)",
              animation: uid + "-scan 3.6s linear infinite",
            }}
          />
        </div>
        {/* glitch bars when damaged/critical */}
        {status !== "normal" && (
          <div
            className="absolute inset-0 pointer-events-none mix-blend-screen"
            style={{
              background: "repeating-linear-gradient(to bottom, " + tone.hex + "40 0 2px, transparent 2px 9px)",
              animation: uid + "-glitch " + (status === "critical" ? "1.6s" : "3s") + " steps(1,end) infinite",
            }}
          />
        )}
        {/* vignette */}
        <div className="absolute inset-0 pointer-events-none shadow-[inset_0_0_26px_rgba(0,0,0,0.9)]" />

        {/* corner brackets */}
        <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="absolute inset-0 h-full w-full pointer-events-none">
          {corner("0.8,14 0.8,0.8 14,0.8", "tl")}
          {corner("86,0.8 99.2,0.8 99.2,14", "tr")}
          {corner("99.2,86 99.2,99.2 86,99.2", "br")}
          {corner("14,99.2 0.8,99.2 0.8,86", "bl")}
        </svg>

        {/* status pip */}
        <div className="absolute right-0 top-0 flex items-center gap-[2px] p-1">
          {[0, 1, 2].map((i) => {
            const lit = status === "critical" ? i < 3 : status === "damaged" ? i < 2 : i < 1;
            return (
              <span
                key={"pip-" + i}
                className={"block h-[3px] w-[6px] transition-all duration-200 " + (lit ? "" : "opacity-20")}
                style={{
                  background: lit ? tone.hex : "#525252",
                  boxShadow: lit ? "0 0 6px " + tone.hex : "none",
                  animation: lit && status === "critical" ? uid + "-pulse 0.7s ease-in-out infinite" : undefined,
                }}
              />
            );
          })}
        </div>
      </div>
    </div>
  );
}

type ListSelectorProps = {
  items: { id: string; label: string; subtitle?: string; category?: string; status?: string; children?: { id: string; label: string; done?: boolean }[] }[];
  value: string | null;
  onChange: (id: string) => void;
  onActivate?: (id: string) => void;
};

export const ListSelector_MIN = {"base":[11,5]};

export function ListSelector(props: ListSelectorProps) {
  const { items, value, onChange, onActivate } = props;
  const uid = useRef("listselector-" + Math.random().toString(36).slice(2)).current;
  const [hover, setHover] = useState<string | null>(null);

  const statusTone = (s?: string) => {
    const t = (s || "").toLowerCase();
    if (t.indexOf("done") >= 0 || t.indexOf("complete") >= 0 || t.indexOf("success") >= 0) return "text-emerald-400 border-emerald-400/50";
    if (t.indexOf("fail") >= 0 || t.indexOf("danger") >= 0 || t.indexOf("critical") >= 0) return "text-rose-500 border-rose-400/50";
    if (t.indexOf("active") >= 0 || t.indexOf("track") >= 0 || t.indexOf("progress") >= 0) return "text-cyan-300 border-cyan-400/50";
    if (t.indexOf("lock") >= 0 || t.indexOf("new") >= 0) return "text-amber-300 border-amber-300/50";
    return "text-fuchsia-400 border-fuchsia-400/40";
  };

  return (
    <div
      className="h-full w-full relative overflow-hidden bg-black/60 ring-1 ring-cyan-400/10 shadow-[inset_0_0_12px_rgba(0,0,0,0.8)]"
      style={{ minWidth: ListSelector_MIN.base[0] + "rem", minHeight: ListSelector_MIN.base[1] + "rem" }}
    >
      <svg className="absolute inset-0 h-full w-full pointer-events-none opacity-40" preserveAspectRatio="none" viewBox="0 0 100 100">
        <defs>
          <linearGradient id={uid + "-sheen"} x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor="rgb(34,211,238)" stopOpacity="0.08" />
            <stop offset="60%" stopColor="rgb(0,0,0)" stopOpacity="0" />
          </linearGradient>
        </defs>
        <rect x="0" y="0" width="100" height="100" fill={"url(#" + uid + "-sheen)"} />
      </svg>

      {items.length === 0 ? (
        <div className="absolute inset-0 flex items-center justify-center">
          <div className="text-[10px] font-medium uppercase tracking-[0.15em] leading-tight text-neutral-500 animate-pulse">// no entries</div>
        </div>
      ) : (
        <div className="absolute inset-0 overflow-y-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
          {items.map((it, i) => {
            const sel = value === it.id;
            const hov = hover === it.id;
            return (
              <div key={it.id} className="relative">
                <div
                  role="button"
                  tabIndex={0}
                  onPointerEnter={() => setHover(it.id)}
                  onPointerLeave={() => setHover((h) => (h === it.id ? null : h))}
                  onClick={() => {
                    if (sel && onActivate) onActivate(it.id);
                    else onChange(it.id);
                  }}
                  onDoubleClick={() => { if (onActivate) onActivate(it.id); }}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      if (sel && onActivate) onActivate(it.id);
                      else onChange(it.id);
                    }
                  }}
                  className={
                    "relative flex items-center gap-2 p-2 cursor-pointer select-none border-b border-cyan-400/10 transition-all duration-200 ease-out focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-300/70 " +
                    (sel
                      ? "bg-cyan-400/10 ring-1 ring-cyan-400/60 text-cyan-200"
                      : hov
                      ? "bg-cyan-400/10"
                      : "bg-transparent")
                  }
                >
                  <span
                    className={
                      "block w-[3px] self-stretch transition-all duration-200 " +
                      (sel ? "bg-cyan-400 shadow-[0_0_12px_rgba(34,211,238,0.8)]" : hov ? "bg-cyan-400/50" : "bg-cyan-400/15")
                    }
                  />
                  <span
                    className={
                      "text-[10px] font-medium uppercase tracking-[0.15em] leading-tight tabular-nums transition-colors duration-200 " +
                      (sel ? "text-cyan-300" : "text-neutral-500")
                    }
                  >
                    {(i + 1 < 10 ? "0" : "") + (i + 1)}
                  </span>

                  <span className="flex-1 min-w-0 flex flex-col gap-[2px]">
                    <span className="flex items-baseline gap-2 min-w-0">
                      <span
                        className={
                          "min-w-0 truncate text-xs font-bold uppercase tracking-[0.18em] leading-none transition-colors duration-200 " +
                          (sel ? "text-cyan-100" : hov ? "text-cyan-200" : "text-cyan-100/80")
                        }
                      >
                        {it.label}
                      </span>
                      {it.category ? (
                        <span className="min-w-0 truncate text-[10px] font-medium uppercase tracking-[0.15em] leading-tight text-fuchsia-400/80">
                          {it.category}
                        </span>
                      ) : null}
                    </span>
                    {it.subtitle ? (
                      <span className="min-w-0 truncate text-[10px] font-medium uppercase tracking-[0.15em] leading-tight text-neutral-400">
                        {it.subtitle}
                      </span>
                    ) : null}
                  </span>

                  {it.status ? (
                    <span
                      className={
                        "min-w-0 truncate max-w-[40%] border rounded-full px-2 py-1 text-[10px] font-medium uppercase tracking-[0.15em] leading-none bg-neutral-800/70 transition-all duration-200 " +
                        statusTone(it.status) +
                        (sel ? " shadow-[0_0_12px_rgba(232,121,249,0.5)]" : "")
                      }
                    >
                      {it.status}
                    </span>
                  ) : null}
                </div>

                {sel && it.children && it.children.length > 0 ? (
                  <div className="bg-black/50 border-b border-cyan-400/10 py-1">
                    {it.children.map((c) => (
                      <div key={c.id} className="flex items-center gap-2 pl-6 pr-2 py-1">
                        <span
                          className={
                            "h-[6px] w-[6px] rotate-45 transition-all duration-200 " +
                            (c.done ? "bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.7)]" : "bg-cyan-400/40 animate-pulse")
                          }
                        />
                        <span
                          className={
                            "min-w-0 truncate text-[10px] font-medium uppercase tracking-[0.15em] leading-tight " +
                            (c.done ? "text-neutral-500 line-through" : "text-cyan-200/70")
                          }
                        >
                          {c.label}
                        </span>
                      </div>
                    ))}
                  </div>
                ) : null}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

type StatReadoutProps = { value: number | string; delta?: number; tone?: 'neutral' | 'accent' | 'danger'; children?: React.ReactNode };

export const StatReadout_MIN = {"base":[3.5,2]};

export function StatReadout(props: StatReadoutProps) {
  const { value, delta, tone = "neutral", children } = props;
  const uid = useRef("statreadout-" + Math.random().toString(36).slice(2)).current;
  const floor = StatReadout_MIN.base;

  const TONES: any = {
    neutral: {
      text: "text-cyan-50",
      accent: "text-cyan-300/80",
      ring: "ring-cyan-400/15",
      bar: "from-cyan-400/70 via-cyan-200/40 to-transparent",
      glow: "0 0 10px rgba(34,211,238,0.35)",
      rgb: "34,211,238",
    },
    accent: {
      text: "text-fuchsia-300",
      accent: "text-fuchsia-300/80",
      ring: "ring-fuchsia-400/25",
      bar: "from-fuchsia-500/80 via-purple-400/40 to-transparent",
      glow: "0 0 14px rgba(232,121,249,0.5)",
      rgb: "232,121,249",
    },
    danger: {
      text: "text-rose-400",
      accent: "text-rose-300/80",
      ring: "ring-rose-400/25",
      bar: "from-rose-500/80 via-red-500/40 to-transparent",
      glow: "0 0 14px rgba(244,63,94,0.5)",
      rgb: "244,63,94",
    },
  };
  const t = TONES[tone] || TONES.neutral;

  const [pulse, setPulse] = useState(0);
  const prev = useRef(value);
  useEffect(() => {
    if (prev.current !== value) {
      prev.current = value;
      setPulse((p) => p + 1);
    }
  }, [value]);

  const hasDelta = typeof delta === "number" && !isNaN(delta as number);
  const dPos = hasDelta && (delta as number) > 0;
  const dNeg = hasDelta && (delta as number) < 0;
  const deltaColor = dPos ? "text-emerald-400" : dNeg ? "text-rose-400" : "text-neutral-500";
  const deltaText = hasDelta
    ? (dPos ? "+" : dNeg ? "\u2212" : "\u00B1") + Math.abs(delta as number)
    : "";

  return (
    <div
      className="relative h-full w-full overflow-hidden"
      style={{ minWidth: floor[0] + "rem", minHeight: floor[1] + "rem" }}
    >
      <style>{
        "@keyframes " + uid + "-flick{0%{opacity:.25;transform:translateY(-6%) scale(1.06)}35%{opacity:1}55%{opacity:.6}100%{opacity:1;transform:translateY(0) scale(1)}}" +
        "@keyframes " + uid + "-sweep{0%{transform:translateX(-110%)}100%{transform:translateX(110%)}}" +
        "@keyframes " + uid + "-pip{0%,100%{opacity:.35}50%{opacity:1}}"
      }</style>

      {/* recessed plate */}
      <div className={"absolute inset-0 bg-black/60 ring-1 " + t.ring + " shadow-[inset_0_0_12px_rgba(0,0,0,0.8)]"} />

      {/* corner notches */}
      <svg className="absolute inset-0 h-full w-full" viewBox="0 0 100 100" preserveAspectRatio="none">
        <path d="M0 0 H14 M0 0 V14" stroke={"rgba(" + t.rgb + ",0.55)"} strokeWidth="2" vectorEffect="non-scaling-stroke" fill="none" />
        <path d="M100 100 H86 M100 100 V86" stroke={"rgba(" + t.rgb + ",0.55)"} strokeWidth="2" vectorEffect="non-scaling-stroke" fill="none" />
      </svg>

      {/* top accent bar */}
      <div className={"absolute left-0 right-0 top-0 h-[3%] min-h-[2px] bg-gradient-to-r " + t.bar} />

      {/* scan sweep */}
      <div className="pointer-events-none absolute inset-0 overflow-hidden">
        <div
          className="absolute -inset-y-2 w-[35%]"
          style={{
            background: "linear-gradient(90deg,transparent,rgba(" + t.rgb + ",0.10),transparent)",
            animation: uid + "-sweep 4.5s linear infinite",
          }}
        />
      </div>

      {/* content */}
      <div className="absolute inset-[7%] flex min-h-0 min-w-0 flex-col">
        <div key={pulse} className="relative min-h-0 min-w-0 flex-1" style={{ animation: uid + "-flick 420ms ease-out" }}>
          <div className="absolute inset-0 flex min-h-0 min-w-0 items-stretch">
            <div className="min-h-0 min-w-0 flex-1">
              <FitText
                className={"font-mono font-bold uppercase tracking-widest transition-colors duration-200 " + t.text}
                wrap={false}
                align={hasDelta ? "start" : "center"}
              >
                {String(value)}
              </FitText>
            </div>
            {hasDelta ? (
              <div className="min-h-0 w-[30%] min-w-0 self-center">
                <FitText className={"font-mono font-bold uppercase tracking-widest " + deltaColor} wrap={false} align="end">
                  {deltaText}
                </FitText>
              </div>
            ) : null}
          </div>
          <div
            className="pointer-events-none absolute inset-0"
            style={{ boxShadow: "inset 0 0 0 0 transparent", textShadow: t.glow }}
          />
        </div>

        {children != null && children !== false ? (
          <div className="mt-[2px] flex min-h-0 min-w-0 items-center gap-1" style={{ height: "34%" }}>
            <div
              className="h-[45%] w-[3px]"
              style={{ background: "rgba(" + t.rgb + ",0.7)", animation: uid + "-pip 2s ease-in-out infinite" }}
            />
            <div className="min-h-0 min-w-0 flex-1">
              <FitText className={"font-mono font-semibold uppercase tracking-[0.18em] " + t.accent} wrap={false} align="start">
                {children}
              </FitText>
            </div>
          </div>
        ) : null}
      </div>
    </div>
  );
}

type MapMarkerProps = {
  id: string;
  position: { x: number; y: number };
  kind?: string;
  state?: "default" | "selected" | "tracked" | "locked";
  onSelect: (id: string) => void;
  onHover?: (id: string | null) => void;
};

export const MapMarker_MIN = {"base":[2,2]};

export function MapMarker(props: MapMarkerProps) {
  const uid = useRef("mapmarker-" + Math.random().toString(36).slice(2)).current;
  const [hot, setHot] = useState(false);
  const [down, setDown] = useState(false);

  const state = props.state || "default";
  const kind = (props.kind || "").toLowerCase();
  const locked = state === "locked";

  const isTravel = kind.indexOf("travel") >= 0 || kind.indexOf("fast") >= 0 || kind.indexOf("transit") >= 0;
  const isQuest = kind.indexOf("quest") >= 0 || kind.indexOf("main") >= 0 || kind.indexOf("job") >= 0 || kind.indexOf("gig") >= 0;
  const isVendor = kind.indexOf("vendor") >= 0 || kind.indexOf("shop") >= 0 || kind.indexOf("ripper") >= 0;

  let accent = "#22d3ee";
  if (isQuest) accent = "#fcd34d";
  if (isVendor) accent = "#e879f9";
  if (state === "tracked") accent = isQuest ? "#fbbf24" : "#22d3ee";
  if (state === "selected") accent = isQuest ? "#fde68a" : "#67e8f9";
  if (locked) accent = "#737373";

  const clampedX = Math.max(0, Math.min(1, props.position.x));
  const clampedY = Math.max(0, Math.min(1, props.position.y));

  const active = state === "selected" || state === "tracked";
  const lift = locked ? 1 : hot ? 1.18 : active ? 1.08 : 1;
  const scale = down && !locked ? lift * 0.9 : lift;
  const glow = locked ? 0 : hot ? 10 : state === "selected" ? 9 : state === "tracked" ? 7 : 3;

  const size = active || hot ? 2.1 : 1.8;

  return (
    <div
      className="relative h-full w-full"
      style={{ minWidth: MapMarker_MIN.base[0] + "rem", minHeight: MapMarker_MIN.base[1] + "rem" }}
    >
      <div
        className="absolute"
        style={{
          left: clampedX * 100 + "%",
          top: clampedY * 100 + "%",
          width: size + "rem",
          height: size + "rem",
          transform: "translate(-50%,-50%) scale(" + scale + ")",
          transition: "transform 200ms ease-out, width 200ms ease-out, height 200ms ease-out",
          opacity: locked ? 0.45 : 1,
          filter: locked ? "grayscale(1)" : "none",
          cursor: locked ? "not-allowed" : "pointer",
          touchAction: "none",
        }}
        onPointerEnter={() => { setHot(true); if (props.onHover) props.onHover(props.id); }}
        onPointerLeave={() => { setHot(false); setDown(false); if (props.onHover) props.onHover(null); }}
        onPointerDown={(e) => { if (locked) return; (e.currentTarget as any).setPointerCapture?.(e.pointerId); setDown(true); }}
        onPointerUp={() => { if (locked) return; setDown(false); props.onSelect(props.id); }}
      >
        <svg viewBox="0 0 100 100" preserveAspectRatio="xMidYMid meet" className="h-full w-full overflow-visible">
          <defs>
            <radialGradient id={uid + "-core"} cx="50%" cy="40%" r="60%">
              <stop offset="0%" stopColor="#ffffff" stopOpacity={locked ? 0.2 : 0.95} />
              <stop offset="55%" stopColor={accent} stopOpacity="0.95" />
              <stop offset="100%" stopColor={accent} stopOpacity="0.15" />
            </radialGradient>
            <filter id={uid + "-blur"} x="-80%" y="-80%" width="260%" height="260%">
              <feGaussianBlur stdDeviation={glow} />
            </filter>
          </defs>

          {glow > 0 ? (
            <circle cx="50" cy="50" r="26" fill={accent} opacity="0.35" filter={"url(#" + uid + "-blur)"} />
          ) : null}

          {state === "tracked" && !locked ? (
            <g>
              <circle cx="50" cy="50" r="40" fill="none" stroke={accent} strokeWidth="2" opacity="0.5">
                <animate attributeName="r" values="30;48;30" dur="2.2s" repeatCount="indefinite" />
                <animate attributeName="opacity" values="0.6;0;0.6" dur="2.2s" repeatCount="indefinite" />
              </circle>
            </g>
          ) : null}

          {/* rotating bracket ring for selected */}
          {state === "selected" && !locked ? (
            <g stroke={accent} strokeWidth="4" fill="none" opacity="0.9">
              <g>
                <path d="M50 8 A42 42 0 0 1 84 30" />
                <path d="M50 92 A42 42 0 0 1 16 70" />
                <animateTransform attributeName="transform" type="rotate" from="0 50 50" to="360 50 50" dur="6s" repeatCount="indefinite" />
              </g>
            </g>
          ) : null}

          {/* static hairline ring */}
          <circle cx="50" cy="50" r="42" fill="none" stroke={accent} strokeOpacity="0.28" strokeWidth="2" strokeDasharray="4 6" />

          {isTravel ? (
            <g>
              <polygon
                points="50,14 81,32 81,68 50,86 19,68 19,32"
                fill="#000000"
                fillOpacity="0.75"
                stroke={accent}
                strokeWidth="5"
                strokeLinejoin="miter"
              />
              <path d="M50 30 L64 52 L54 52 L54 70 L46 70 L46 52 L36 52 Z" fill={"url(#" + uid + "-core)"} />
            </g>
          ) : isQuest ? (
            <g>
              <polygon points="50,12 88,50 50,88 12,50" fill="#000000" fillOpacity="0.75" stroke={accent} strokeWidth="5" strokeLinejoin="miter" />
              <rect x="45" y="30" width="10" height="26" fill={"url(#" + uid + "-core)"} />
              <rect x="45" y="61" width="10" height="9" fill={accent} />
            </g>
          ) : (
            <g>
              <polygon points="50,16 84,50 50,84 16,50" fill="#000000" fillOpacity="0.7" stroke={accent} strokeWidth="4" strokeLinejoin="miter" opacity="0.8" />
              <circle cx="50" cy="50" r="15" fill={"url(#" + uid + "-core)"} />
            </g>
          )}

          {/* crosshair ticks */}
          <g stroke={accent} strokeWidth="4" strokeLinecap="butt" opacity={hot && !locked ? 0.95 : 0.4}>
            <line x1="50" y1="0" x2="50" y2="8" />
            <line x1="50" y1="92" x2="50" y2="100" />
            <line x1="0" y1="50" x2="8" y2="50" />
            <line x1="92" y1="50" x2="100" y2="50" />
          </g>

          {locked ? (
            <g stroke="#a3a3a3" strokeWidth="6" strokeLinecap="round">
              <line x1="34" y1="34" x2="66" y2="66" />
              <line x1="66" y1="34" x2="34" y2="66" />
            </g>
          ) : null}
        </svg>
      </div>
    </div>
  );
}

type PerkNodeProps = { state: 'locked' | 'available' | 'unlocked'; rank: number; maxRank: number; onSpend: (id: string) => void; id: string; hover?: (id: string | null) => void; children?: React.ReactNode };

export const PerkNode_MIN = {"base":[3.5,3.5]};

const PerkNodeHexPath = (r: number) => {
  let d = "";
  for (let i = 0; i < 6; i++) {
    const a = (Math.PI / 180) * (60 * i - 90);
    const x = 50 + r * Math.cos(a);
    const y = 50 + r * Math.sin(a);
    d += (i === 0 ? "M" : "L") + x.toFixed(2) + " " + y.toFixed(2) + " ";
  }
  return d + "Z";
};

const PerkNodeArc = (r: number, a0: number, a1: number) => {
  const p = (a: number) => {
    const rad = (Math.PI / 180) * (a - 90);
    return [50 + r * Math.cos(rad), 50 + r * Math.sin(rad)];
  };
  const [x0, y0] = p(a0);
  const [x1, y1] = p(a1);
  const large = a1 - a0 > 180 ? 1 : 0;
  return "M" + x0.toFixed(2) + " " + y0.toFixed(2) + " A" + r + " " + r + " 0 " + large + " 1 " + x1.toFixed(2) + " " + y1.toFixed(2);
};

export function PerkNode(props: PerkNodeProps) {
  const { state, rank, maxRank, onSpend, id, hover, children } = props;
  const uid = useRef("perknode-" + Math.random().toString(36).slice(2)).current;
  const [hot, setHot] = useState(false);
  const [press, setPress] = useState(false);
  const [pulse, setPulse] = useState(0);
  const prevRank = useRef(rank);

  useEffect(() => {
    if (rank !== prevRank.current) {
      prevRank.current = rank;
      setPulse((p) => p + 1);
    }
  }, [rank]);

  const floor = PerkNode_MIN.base;
  const locked = state === "locked";
  const maxed = rank >= maxRank && maxRank > 0;
  const interactive = !locked && !maxed;

  const accent = locked ? "#737373" : state === "unlocked" ? "#e879f9" : "#22d3ee";
  const accentDim = locked ? "rgba(115,115,115,0.25)" : state === "unlocked" ? "rgba(232,121,249,0.28)" : "rgba(34,211,238,0.25)";
  const glow = hot && interactive ? 1 : 0;

  const segs = Math.max(0, Math.min(maxRank, 12));
  const gapDeg = segs > 1 ? Math.min(10, 120 / segs) : 0;
  const span = segs > 0 ? 360 / segs : 360;

  const textColor = locked ? "text-neutral-500" : state === "unlocked" ? "text-fuchsia-300" : "text-cyan-200";

  return (
    <div
      className="relative h-full w-full"
      style={{ minWidth: floor[0] + "rem", minHeight: floor[1] + "rem" }}
      onPointerEnter={() => { setHot(true); if (hover) hover(id); }}
      onPointerLeave={() => { setHot(false); setPress(false); if (hover) hover(null); }}
      onPointerDown={(e) => { if (!interactive) return; (e.currentTarget as any).setPointerCapture?.(e.pointerId); setPress(true); }}
      onPointerUp={() => { if (press && interactive) onSpend(id); setPress(false); }}
      onPointerCancel={() => setPress(false)}
    >
      <div
        className={"absolute inset-0 transition-all duration-200 ease-out touch-none " + (locked ? "opacity-40 grayscale" : "") + (interactive ? " cursor-pointer" : "")}
        style={{ transform: press ? "scale(0.95)" : hot && interactive ? "scale(1.04)" : "scale(1)" }}
      >
        <svg viewBox="0 0 100 100" preserveAspectRatio="xMidYMid meet" className="absolute inset-0 h-full w-full">
          <defs>
            <radialGradient id={uid + "-core"} cx="50%" cy="38%" r="70%">
              <stop offset="0%" stopColor={accent} stopOpacity={state === "unlocked" ? 0.45 : locked ? 0.06 : 0.18 + glow * 0.18} />
              <stop offset="60%" stopColor="#000000" stopOpacity="0.85" />
              <stop offset="100%" stopColor="#000000" stopOpacity="0.95" />
            </radialGradient>
            <linearGradient id={uid + "-edge"} x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor={accent} stopOpacity={locked ? 0.4 : 1} />
              <stop offset="100%" stopColor={accent} stopOpacity={locked ? 0.15 : 0.45} />
            </linearGradient>
            <filter id={uid + "-blur"} x="-60%" y="-60%" width="220%" height="220%">
              <feGaussianBlur stdDeviation={2.5 + glow * 2} />
            </filter>
          </defs>

          {/* outer glow halo */}
          {!locked && (
            <path
              d={PerkNodeHexPath(42)}
              fill="none"
              stroke={accent}
              strokeWidth={state === "unlocked" ? 4 : 2.5}
              opacity={state === "unlocked" ? 0.55 : 0.25 + glow * 0.4}
              filter={"url(#" + uid + "-blur)"}
              className="transition-all duration-200 ease-out"
            />
          )}

          {/* body */}
          <path d={PerkNodeHexPath(42)} fill={"url(#" + uid + "-core")" } />
          <path
            d={PerkNodeHexPath(42)}
            fill="none"
            stroke={"url(#" + uid + "-edge)"}
            strokeWidth={state === "unlocked" ? 3 : 2}
            strokeLinejoin="miter"
            className="transition-all duration-200 ease-out"
          />

          {/* inner etch */}
          <path d={PerkNodeHexPath(33)} fill="none" stroke={accent} strokeOpacity={0.18} strokeWidth="0.7" strokeDasharray="4 3" />

          {/* rank segments */}
          {segs > 0 && Array.from({ length: segs }).map((_, i) => {
            const a0 = i * span + gapDeg / 2;
            const a1 = (i + 1) * span - gapDeg / 2;
            const filled = i < rank;
            return (
              <path
                key={"seg-" + i}
                d={PerkNodeArc(47, a0, a1)}
                fill="none"
                stroke={filled ? accent : accentDim}
                strokeWidth={filled ? 4 : 2.2}
                strokeLinecap="butt"
                opacity={filled ? 1 : 0.6}
                className="transition-all duration-300 ease-out"
              />
            );
          })}

          {/* corner cursors when available */}
          {state === "available" && !locked && (
            <g opacity={0.5 + glow * 0.5} className="transition-all duration-200 ease-out">
              <path d="M50 4 L46 10 L54 10 Z" fill={accent} />
              <path d="M50 96 L46 90 L54 90 Z" fill={accent} />
            </g>
          )}

          {/* locked latch */}
          {locked && (
            <g stroke="#a3a3a3" strokeWidth="2.2" fill="none" opacity="0.8">
              <rect x="42" y="70" width="16" height="12" rx="1.5" fill="#0a0a0a" />
              <path d="M45.5 70 v-4 a4.5 4.5 0 0 1 9 0 v4" />
            </g>
          )}

          {/* maxed spark */}
          {maxed && !locked && (
            <circle cx="50" cy="50" r="46" fill="none" stroke={accent} strokeOpacity="0.25" strokeWidth="0.8" className="animate-pulse" />
          )}

          {/* value-change ping */}
          {pulse > 0 && (
            <circle key={"ping-" + pulse} cx="50" cy="50" r="30" fill="none" stroke={accent} strokeWidth="3" className="animate-ping" opacity="0.6" />
          )}
        </svg>

        {children != null && children !== false && (
          <div className="absolute inset-[26%] flex items-center justify-center">
            <FitText className={"font-mono font-bold tracking-widest uppercase transition-colors duration-200 " + textColor}>{children}</FitText>
          </div>
        )}
      </div>
    </div>
  );
}

type ItemGridProps = { items: { id: string; label: string; icon?: string; rarity?: string; quantity?: number; stats?: { label: string; value: number | string }[]; equipped?: boolean }[]; value: string | null; onChange: (id: string) => void; onActivate?: (id: string) => void };

const ItemGridRarity: Record<string, { text: string; border: string; glow: string; bg: string }> = {
  common: { text: "text-neutral-300", border: "border-neutral-500/60", glow: "0 0 10px rgba(163,163,163,0.35)", bg: "from-neutral-700/25" },
  uncommon: { text: "text-emerald-400", border: "border-emerald-400/60", glow: "0 0 12px rgba(52,211,153,0.45)", bg: "from-emerald-500/20" },
  rare: { text: "text-cyan-300", border: "border-cyan-400/60", glow: "0 0 12px rgba(34,211,238,0.5)", bg: "from-cyan-500/20" },
  epic: { text: "text-fuchsia-400", border: "border-fuchsia-400/60", glow: "0 0 14px rgba(232,121,249,0.5)", bg: "from-fuchsia-500/20" },
  legendary: { text: "text-amber-300", border: "border-amber-300/60", glow: "0 0 16px rgba(252,211,77,0.55)", bg: "from-amber-400/25" },
};

export const ItemGrid_MIN = {"base":[11,7.5]};

export function ItemGrid(props: ItemGridProps) {
  const { items, value, onChange, onActivate } = props;
  const uid = useRef("itemgrid-" + Math.random().toString(36).slice(2)).current;
  const [hover, setHover] = useState<string | null>(null);
  const [pulse, setPulse] = useState<string | null>(null);

  const rarityOf = (r?: string) => ItemGridRarity[(r || "common").toLowerCase()] || ItemGridRarity.common;

  const fire = (id: string) => {
    if (!onActivate) return;
    onActivate(id);
    setPulse(id);
    window.setTimeout(() => setPulse((p) => (p === id ? null : p)), 420);
  };

  return (
    <div
      className="h-full w-full relative"
      style={{ minWidth: ItemGrid_MIN.base[0] + "rem", minHeight: ItemGrid_MIN.base[1] + "rem" }}
    >
      <div className="absolute inset-0 bg-black/60 ring-1 ring-cyan-400/10 shadow-[inset_0_0_12px_rgba(0,0,0,0.8)] overflow-hidden">
        <div className="absolute inset-0 overflow-y-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
          {items.length === 0 ? (
            <div className="h-full w-full min-h-[5rem] flex items-center justify-center">
              <div className="text-[10px] font-medium uppercase tracking-[0.15em] leading-tight text-neutral-500 border border-cyan-400/15 px-2 py-1">
                // no items
              </div>
            </div>
          ) : (
            <div
              className="grid gap-[2px] p-[2px]"
              style={{ gridTemplateColumns: "repeat(auto-fill, minmax(5.25rem, 1fr))" }}
            >
              {items.map((it, i) => {
                const r = rarityOf(it.rarity);
                const sel = value === it.id;
                const hov = hover === it.id;
                const pul = pulse === it.id;
                return (
                  <div
                    key={it.id}
                    onPointerEnter={() => setHover(it.id)}
                    onPointerLeave={() => setHover((h) => (h === it.id ? null : h))}
                    onPointerDown={() => onChange(it.id)}
                    onDoubleClick={() => fire(it.id)}
                    className={
                      "group relative select-none cursor-pointer rounded-sm border bg-gradient-to-b " +
                      r.bg +
                      " to-neutral-950/90 transition-all duration-200 ease-out active:scale-[0.97] active:brightness-125 " +
                      (sel ? r.border + " ring-1 ring-cyan-400/60 " : "border-cyan-400/20 ")
                    }
                    style={{
                      minHeight: "4.6rem",
                      boxShadow: sel || hov ? r.glow : "none",
                      animationDuration: "0.4s",
                    }}
                  >
                    {/* corner brackets */}
                    <span className={"pointer-events-none absolute left-0 top-0 h-2 w-2 border-l border-t transition-all duration-200 " + (sel ? r.border : "border-cyan-400/25")} />
                    <span className={"pointer-events-none absolute right-0 bottom-0 h-2 w-2 border-r border-b transition-all duration-200 " + (sel ? r.border : "border-cyan-400/25")} />

                    {/* rarity spine */}
                    <span
                      className={"pointer-events-none absolute left-0 top-0 bottom-0 w-[2px] transition-all duration-200 " + (sel || hov ? "opacity-100" : "opacity-50")}
                      style={{ background: "currentColor" }}
                    />
                    <div className={"absolute inset-0 " + r.text} style={{ pointerEvents: "none" }}>
                      <span className="absolute left-0 top-0 bottom-0 w-[2px] bg-current" style={{ boxShadow: sel || hov ? r.glow : "none" }} />
                    </div>

                    {/* scan sweep on hover */}
                    <span
                      className={"pointer-events-none absolute inset-0 overflow-hidden rounded-sm transition-opacity duration-200 " + (hov ? "opacity-100" : "opacity-0")}
                    >
                      <span
                        className="absolute -inset-y-2 w-1/3 bg-gradient-to-r from-transparent via-cyan-300/15 to-transparent"
                        style={{ animation: hov ? "itemgridsweep 1.4s linear infinite" : "none" }}
                      />
                    </span>

                    <div className="relative h-full w-full flex flex-col p-2 gap-1">
                      {/* face: icon */}
                      <div className="relative flex-1 min-h-0 min-w-0 flex items-center justify-center">
                        <div className="absolute inset-[8%]">
                          <FitText
                            wrap={false}
                            className={"font-mono font-bold tracking-widest uppercase transition-all duration-200 " + r.text + (pul ? " brightness-150" : "")}
                          >
                            {it.icon && it.icon.length > 0 ? it.icon : it.label.slice(0, 2)}
                          </FitText>
                        </div>
                      </div>

                      {/* name */}
                      <div className={"min-w-0 truncate text-[10px] font-medium uppercase tracking-[0.15em] leading-tight transition-colors duration-150 " + (sel ? "text-cyan-100" : "text-cyan-200/70")}>
                        {it.label}
                      </div>

                      {/* stats */}
                      {it.stats && it.stats.length > 0 ? (
                        <div className="flex flex-wrap gap-x-2 gap-y-[1px] overflow-hidden" style={{ maxHeight: "1.6rem" }}>
                          {it.stats.slice(0, 2).map((s, k) => (
                            <span key={"s-" + k} className="min-w-0 truncate text-[10px] font-medium uppercase tracking-[0.1em] leading-tight text-neutral-400">
                              <span className="text-neutral-500">{s.label}</span>{" "}
                              <span className={r.text}>{s.value}</span>
                            </span>
                          ))}
                        </div>
                      ) : null}
                    </div>

                    {/* quantity badge */}
                    {typeof it.quantity === "number" ? (
                      <span className="absolute right-1 top-1 rounded-sm border border-cyan-400/30 bg-black/70 px-1 text-[10px] font-semibold leading-tight tracking-[0.1em] text-cyan-200/80">
                        {"x" + it.quantity}
                      </span>
                    ) : null}

                    {/* equipped marker */}
                    {it.equipped ? (
                      <span className="absolute right-1 bottom-1 rounded-full border border-fuchsia-400/40 bg-fuchsia-500/25 px-2 text-[10px] font-semibold uppercase leading-tight tracking-[0.15em] text-fuchsia-200 shadow-[0_0_12px_rgba(232,121,249,0.5)] animate-pulse">
                        EQ
                      </span>
                    ) : null}

                    {/* activate flash */}
                    {pul ? (
                      <span
                        className="pointer-events-none absolute inset-0 rounded-sm bg-cyan-300/25"
                        style={{ animation: "itemgridflash 0.42s ease-out forwards" }}
                      />
                    ) : null}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
      <style>{
        "@keyframes itemgridsweep{0%{transform:translateX(-120%)}100%{transform:translateX(420%)}}" +
        "@keyframes itemgridflash{0%{opacity:.9;transform:scale(1)}100%{opacity:0;transform:scale(1.06)}}"
      }</style>
      <span className="hidden">{uid}</span>
    </div>
  );
}

type ZoomControlProps = { value: number; min: number; max: number; step?: number; onChange: (zoom: number) => void; onReset?: () => void };

export const ZoomControl_MIN = {"base":[2.25,7.5]};

export function ZoomControl(props: ZoomControlProps) {
  const { value, min, max, step, onChange, onReset } = props;
  const uid = useRef("zoomcontrol-" + Math.random().toString(36).slice(2)).current;
  const trackRef = useRef<HTMLDivElement | null>(null);
  const [drag, setDrag] = useState(false);
  const [pulse, setPulse] = useState(0);

  const span = Math.max(1e-6, max - min);
  const clamp = (v: number) => Math.min(max, Math.max(min, v));
  const snap = (v: number) => {
    if (!step || step <= 0) return clamp(v);
    const n = Math.round((v - min) / step);
    return clamp(min + n * step);
  };
  const frac = Math.min(1, Math.max(0, (clamp(value) - min) / span));

  useEffect(() => { setPulse((p) => p + 1); }, [value]);

  const emit = (v: number) => { const nv = snap(v); if (nv !== value) onChange(nv); };
  const stepAmt = step && step > 0 ? step : span / 8;

  const fromPointer = (e: any) => {
    const el = trackRef.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    if (r.height <= 0) return;
    const f = 1 - (e.clientY - r.top) / r.height;
    emit(min + Math.min(1, Math.max(0, f)) * span);
  };

  const ticks: number[] = [];
  if (step && step > 0) {
    const n = Math.round(span / step);
    if (n > 1 && n <= 24) for (let i = 0; i <= n; i++) ticks.push(i / n);
  }

  const btn =
    "relative w-full flex items-center justify-center border border-cyan-300/40 bg-neutral-800/80 text-cyan-300 " +
    "transition-all duration-200 ease-out hover:bg-cyan-300 hover:text-black hover:border-cyan-200 " +
    "hover:shadow-[0_0_16px_rgba(34,211,238,0.5)] active:scale-[0.94] active:brightness-110 " +
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-300/70 disabled:opacity-40 disabled:grayscale";

  const Glyph = (p: { kind: "plus" | "minus" | "reset" }) => (
    <svg viewBox="0 0 24 24" preserveAspectRatio="xMidYMid meet" className="h-[70%] w-[70%]" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="square">
      {p.kind === "plus" ? <g><path d="M12 5.5v13" /><path d="M5.5 12h13" /></g> : null}
      {p.kind === "minus" ? <path d="M5.5 12h13" /> : null}
      {p.kind === "reset" ? <g><path d="M12 6.5a5.5 5.5 0 1 1-5.2 3.7" /><path d="M6.2 5.2v5h5" /></g> : null}
    </svg>
  );

  return (
    <div
      className="h-full w-full flex flex-col items-center justify-stretch"
      style={{ minWidth: ZoomControl_MIN.base[0] + "rem", minHeight: ZoomControl_MIN.base[1] + "rem" }}
    >
      <div className="h-full flex flex-col items-stretch gap-[2%] w-full" style={{ maxWidth: "3.25rem" }}>
        <button
          type="button"
          aria-label="zoom in"
          disabled={value >= max - 1e-9}
          onClick={() => emit(value + stepAmt)}
          className={btn}
          style={{ height: "1.6rem", flex: "0 0 auto" }}
        >
          <Glyph kind="plus" />
        </button>

        <div
          ref={trackRef}
          onPointerDown={(e) => { (e.target as any).setPointerCapture?.(e.pointerId); setDrag(true); fromPointer(e); }}
          onPointerMove={(e) => { if (drag) fromPointer(e); }}
          onPointerUp={() => setDrag(false)}
          onPointerCancel={() => setDrag(false)}
          className="relative flex-1 min-h-0 w-full touch-none cursor-pointer bg-black/60 border border-cyan-400/25 shadow-[inset_0_0_12px_rgba(0,0,0,0.8)] ring-1 ring-cyan-400/10 overflow-hidden"
        >
          {/* scan grid */}
          <div className="absolute inset-0 opacity-40" style={{ backgroundImage: "repeating-linear-gradient(to bottom, rgba(34,211,238,0.10) 0px, rgba(34,211,238,0.10) 1px, transparent 1px, transparent 6px)" }} />
          {/* fill */}
          <div
            className="absolute left-0 right-0 bottom-0 bg-gradient-to-t from-cyan-400 to-cyan-200 shadow-[0_0_8px_rgba(34,211,238,0.6)] transition-all duration-200 ease-out"
            style={{ height: (frac * 100) + "%", opacity: 0.85 }}
          />
          {/* ticks */}
          {ticks.map((t, i) => (
            <div
              key={"tk-" + uid + "-" + i}
              className="absolute right-0 bg-cyan-200/50"
              style={{ bottom: (t * 100) + "%", height: "1px", width: i % 2 === 0 ? "45%" : "25%" }}
            />
          ))}
          {/* thumb */}
          <div
            className="absolute left-0 right-0 transition-all duration-150 ease-out"
            style={{ bottom: "calc(" + (frac * 100) + "% - 0.3rem)", height: "0.6rem" }}
          >
            <div
              className={
                "absolute inset-0 border bg-neutral-900/90 " +
                (drag ? "border-fuchsia-300 shadow-[0_0_12px_rgba(232,121,249,0.5)]" : "border-cyan-300/70 shadow-[0_0_10px_rgba(34,211,238,0.45)]")
              }
            >
              <div className={"absolute left-[12%] right-[12%] top-1/2 h-[2px] -translate-y-1/2 " + (drag ? "bg-fuchsia-400" : "bg-cyan-300")} />
            </div>
          </div>
          {/* value pulse */}
          <div
            key={"pl-" + uid + "-" + pulse}
            className="absolute left-0 right-0 h-[2px] bg-cyan-100/80 pointer-events-none"
            style={{ bottom: (frac * 100) + "%", animation: "none", opacity: drag ? 0.9 : 0.35 }}
          />
        </div>

        <button
          type="button"
          aria-label="zoom out"
          disabled={value <= min + 1e-9}
          onClick={() => emit(value - stepAmt)}
          className={btn}
          style={{ height: "1.6rem", flex: "0 0 auto" }}
        >
          <Glyph kind="minus" />
        </button>

        {onReset ? (
          <button
            type="button"
            aria-label="reset zoom"
            onClick={() => onReset()}
            className={
              "relative w-full flex items-center justify-center border border-fuchsia-400/40 bg-neutral-800/70 text-fuchsia-400 " +
              "transition-all duration-150 ease-out hover:bg-fuchsia-500/25 hover:border-fuchsia-300 hover:text-fuchsia-200 " +
              "hover:shadow-[0_0_12px_rgba(232,121,249,0.5)] active:scale-[0.94] " +
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-300/70"
            }
            style={{ height: "1.4rem", flex: "0 0 auto" }}
          >
            <Glyph kind="reset" />
          </button>
        ) : null}
      </div>
    </div>
  );
}

type EquipmentSlotProps = {
  item: { id: string; label: string; icon?: string; rarity?: string } | null;
  slotId: string;
  onSelect: (slotId: string) => void;
  onClear?: (slotId: string) => void;
  accepts?: string;
};

export const EquipmentSlot_MIN = {"base":[5,3.5]};

const EquipmentSlotRarity: Record<string, { text: string; border: string; glow: string; rgb: string }> = {
  common: { text: "text-neutral-300", border: "border-neutral-500/60", glow: "rgba(163,163,163,0.35)", rgb: "163,163,163" },
  uncommon: { text: "text-emerald-400", border: "border-emerald-400/60", glow: "rgba(52,211,153,0.45)", rgb: "52,211,153" },
  rare: { text: "text-cyan-300", border: "border-cyan-400/60", glow: "rgba(34,211,238,0.5)", rgb: "34,211,238" },
  epic: { text: "text-fuchsia-400", border: "border-fuchsia-400/60", glow: "rgba(232,121,249,0.5)", rgb: "232,121,249" },
  legendary: { text: "text-amber-300", border: "border-amber-300/60", glow: "rgba(252,211,77,0.5)", rgb: "252,211,77" },
};

export function EquipmentSlot(props: EquipmentSlotProps) {
  const { item, slotId, onSelect, onClear, accepts } = props;
  const uid = useRef("eqslot-" + Math.random().toString(36).slice(2)).current;
  const [press, setPress] = useState(false);
  const [flash, setFlash] = useState(false);
  const prevId = useRef<string | null>(item ? item.id : null);

  useEffect(() => {
    const cur = item ? item.id : null;
    if (cur !== prevId.current) {
      prevId.current = cur;
      if (cur) {
        setFlash(true);
        const t = setTimeout(() => setFlash(false), 500);
        return () => clearTimeout(t);
      }
    }
  }, [item]);

  const rar = (item && item.rarity && EquipmentSlotRarity[item.rarity.toLowerCase()]) || null;
  const accent = rar || { text: "text-cyan-300", border: "border-cyan-400/40", glow: "rgba(34,211,238,0.4)", rgb: "34,211,238" };
  const floor = EquipmentSlot_MIN.base;
  const clip = "polygon(0 0, calc(100% - 0.55rem) 0, 100% 0.55rem, 100% 100%, 0.55rem 100%, 0 calc(100% - 0.55rem))";

  return (
    <div
      className="relative h-full w-full"
      style={{ minWidth: floor[0] + "rem", minHeight: floor[1] + "rem" }}
    >
      <button
        type="button"
        onClick={() => onSelect(slotId)}
        onPointerDown={() => setPress(true)}
        onPointerUp={() => setPress(false)}
        onPointerLeave={() => setPress(false)}
        className={
          "group absolute inset-0 block touch-none overflow-hidden border text-left transition-all duration-200 ease-out focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-300/70 " +
          (item
            ? accent.border + " bg-neutral-900/85 "
            : "border-cyan-400/20 bg-black/60 ") +
          (press ? "brightness-125 scale-[0.975] " : "")
        }
        style={{
          clipPath: clip,
          boxShadow: item
            ? "inset 0 0 14px rgba(0,0,0,0.85), 0 0 " + (press ? "18px " : "10px ") + accent.glow
            : "inset 0 0 12px rgba(0,0,0,0.8)",
        }}
      >
        {/* base gradient */}
        <span
          className="pointer-events-none absolute inset-0 transition-opacity duration-200"
          style={{
            background: item
              ? "linear-gradient(140deg, rgba(" + accent.rgb + ",0.16) 0%, rgba(10,10,12,0.9) 55%, rgba(0,0,0,0.95) 100%)"
              : "repeating-linear-gradient(135deg, rgba(34,211,238,0.06) 0 2px, rgba(0,0,0,0) 2px 9px)",
          }}
        />
        {/* scanlines */}
        <span
          className="pointer-events-none absolute inset-0 opacity-30"
          style={{ background: "repeating-linear-gradient(to bottom, rgba(255,255,255,0.05) 0 1px, rgba(0,0,0,0) 1px 4px)" }}
        />
        {/* hover sweep */}
        <span
          className="pointer-events-none absolute inset-y-0 -left-1/3 w-1/3 -skew-x-12 opacity-0 transition-all duration-500 ease-out group-hover:left-[110%] group-hover:opacity-100"
          style={{ background: "linear-gradient(90deg, rgba(0,0,0,0), rgba(" + accent.rgb + ",0.28), rgba(0,0,0,0))" }}
        />
        {/* equip flash */}
        {flash && (
          <span
            className="pointer-events-none absolute inset-0 animate-ping"
            style={{ background: "rgba(" + accent.rgb + ",0.18)" }}
          />
        )}

        {/* corner brackets */}
        <svg className="pointer-events-none absolute inset-0 h-full w-full" viewBox="0 0 100 100" preserveAspectRatio="none">
          <defs>
            <linearGradient id={uid + "-edge"} x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stopColor={"rgba(" + accent.rgb + ",0.9)"} />
              <stop offset="100%" stopColor={"rgba(" + accent.rgb + ",0.25)"} />
            </linearGradient>
          </defs>
          <path d="M0 0 H16 M0 0 V18" stroke={"url(#" + uid + "-edge)"} strokeWidth="3" fill="none" vectorEffect="non-scaling-stroke" />
          <path d="M100 100 H84 M100 100 V82" stroke={"url(#" + uid + "-edge)"} strokeWidth="3" fill="none" vectorEffect="non-scaling-stroke" />
        </svg>

        {/* content */}
        <span className="absolute inset-0 flex items-stretch gap-2 p-2">
          {/* icon / empty mark */}
          <span className="relative aspect-square h-full max-w-[42%] shrink">
            <span
              className={
                "absolute inset-0 border transition-all duration-200 " +
                (item ? accent.border : "border-cyan-400/20 border-dashed")
              }
              style={{
                clipPath: "polygon(18% 0, 100% 0, 100% 82%, 82% 100%, 0 100%, 0 18%)",
                background: item ? "rgba(" + accent.rgb + ",0.10)" : "rgba(0,0,0,0.4)",
              }}
            />
            {item ? (
              item.icon ? (
                <span className="absolute inset-[16%]">
                  <FitText className={"font-mono font-bold tracking-widest uppercase " + accent.text} wrap={false}>
                    {item.icon}
                  </FitText>
                </span>
              ) : (
                <svg className="absolute inset-[22%] h-auto w-auto" viewBox="0 0 24 24" preserveAspectRatio="xMidYMid meet" style={{ width: "56%", height: "56%", left: "22%", top: "22%" }}>
                  <path d="M12 2 L21 7 V17 L12 22 L3 17 V7 Z" fill="none" stroke={"rgba(" + accent.rgb + ",0.85)"} strokeWidth="1.6" />
                  <path d="M12 7 L16.5 9.5 V14.5 L12 17 L7.5 14.5 V9.5 Z" fill={"rgba(" + accent.rgb + ",0.35)"} />
                </svg>
              )
            ) : (
              <svg className="absolute left-[25%] top-[25%]" style={{ width: "50%", height: "50%" }} viewBox="0 0 24 24" preserveAspectRatio="xMidYMid meet">
                <path d="M12 4 V20 M4 12 H20" stroke="rgba(34,211,238,0.5)" strokeWidth="2" strokeLinecap="square" className="transition-all duration-200 group-hover:stroke-[rgba(34,211,238,0.95)]" />
              </svg>
            )}
          </span>

          {/* label region */}
          <span className="relative flex min-w-0 flex-1 flex-col justify-center overflow-hidden">
            {item ? (
              <span className="relative min-h-0 min-w-0 flex-1">
                <span className="absolute inset-0 flex items-center">
                  <span className="relative h-full w-full">
                    <FitText className={"font-mono font-bold uppercase tracking-widest transition-colors duration-200 " + accent.text} align="start">
                      {item.label}
                    </FitText>
                  </span>
                </span>
              </span>
            ) : accepts ? (
              <span className="min-w-0 truncate text-[10px] font-medium uppercase tracking-[0.15em] leading-tight text-neutral-500 transition-colors duration-200 group-hover:text-cyan-300/80">
                {accepts}
              </span>
            ) : (
              <span className="h-px w-full bg-cyan-400/20" />
            )}
            {item && accepts ? (
              <span className="min-w-0 truncate text-[10px] font-medium uppercase tracking-[0.15em] leading-tight text-neutral-500">
                {accepts}
              </span>
            ) : null}
          </span>
        </span>
      </button>

      {/* clear */}
      {item && onClear ? (
        <button
          type="button"
          onClick={(e) => { e.stopPropagation(); onClear(slotId); }}
          className="absolute right-0 top-0 z-10 flex h-4 w-4 items-center justify-center border border-rose-400/50 bg-black/70 text-rose-500 transition-all duration-200 ease-out hover:bg-rose-600 hover:text-white hover:shadow-[0_0_12px_rgba(244,63,94,0.6)] active:scale-[0.9] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-300/70"
        >
          <svg viewBox="0 0 12 12" className="h-2.5 w-2.5" preserveAspectRatio="xMidYMid meet">
            <path d="M2 2 L10 10 M10 2 L2 10" stroke="currentColor" strokeWidth="2" strokeLinecap="square" />
          </svg>
        </button>
      ) : null}
    </div>
  );
}

type MapCanvasProps = {
  regions: { id: string; label: string; path?: string; bounds?: { x: number; y: number; w: number; h: number } }[];
  center: { x: number; y: number };
  zoom: number;
  onViewChange: (view: { center: { x: number; y: number }; zoom: number }) => void;
  children?: React.ReactNode;
};

export function MapCanvas(props: MapCanvasProps) {
  const { regions, center, zoom, onViewChange, children } = props;
  const uid = useRef("mapcanvas-" + Math.random().toString(36).slice(2)).current;
  const floor = MapCanvas_MIN.base;

  const S = 1000;
  const z = Math.max(0.5, Math.min(8, zoom || 1));
  const half = (S * 0.5) / z;
  const cx = Math.max(0, Math.min(1, center ? center.x : 0.5));
  const cy = Math.max(0, Math.min(1, center ? center.y : 0.5));
  const vb = (cx * S - half) + " " + (cy * S - half) + " " + half * 2 + " " + half * 2;

  const hostRef = useRef<HTMLDivElement | null>(null);
  const drag = useRef<{ id: number; px: number; py: number; cx: number; cy: number } | null>(null);
  const pinch = useRef<Map<number, { x: number; y: number }>>(new Map());
  const pinchStart = useRef<{ dist: number; zoom: number } | null>(null);
  const [active, setActive] = useState(false);
  const [hover, setHover] = useState<string | null>(null);

  const clamp01 = (v: number) => Math.max(0, Math.min(1, v));

  const emit = (nx: number, ny: number, nz: number) => {
    onViewChange({ center: { x: clamp01(nx), y: clamp01(ny) }, zoom: Math.max(0.5, Math.min(8, nz)) });
  };

  const onDown = (e: React.PointerEvent) => {
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    pinch.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pinch.current.size === 2) {
      const pts = Array.from(pinch.current.values());
      const d = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
      pinchStart.current = { dist: d || 1, zoom: z };
      drag.current = null;
    } else {
      drag.current = { id: e.pointerId, px: e.clientX, py: e.clientY, cx: cx, cy: cy };
    }
    setActive(true);
  };

  const onMove = (e: React.PointerEvent) => {
    if (pinch.current.has(e.pointerId)) pinch.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    const host = hostRef.current;
    if (!host) return;
    const r = host.getBoundingClientRect();
    if (r.width <= 0 || r.height <= 0) return;
    if (pinch.current.size >= 2 && pinchStart.current) {
      const pts = Array.from(pinch.current.values());
      const d = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
      emit(cx, cy, pinchStart.current.zoom * (d / pinchStart.current.dist));
      return;
    }
    const d0 = drag.current;
    if (!d0 || d0.id !== e.pointerId) return;
    const span = Math.min(r.width, r.height);
    const dx = (e.clientX - d0.px) / span / z;
    const dy = (e.clientY - d0.py) / span / z;
    emit(d0.cx - dx, d0.cy - dy, z);
  };

  const onUp = (e: React.PointerEvent) => {
    pinch.current.delete(e.pointerId);
    if (pinch.current.size < 2) pinchStart.current = null;
    if (drag.current && drag.current.id === e.pointerId) drag.current = null;
    if (pinch.current.size === 0) setActive(false);
  };

  const onDouble = (e: React.MouseEvent) => {
    const host = hostRef.current;
    if (!host) return;
    const r = host.getBoundingClientRect();
    if (r.width <= 0 || r.height <= 0) return;
    const span = Math.min(r.width, r.height);
    const ux = (e.clientX - r.left - r.width / 2) / span / z;
    const uy = (e.clientY - r.top - r.height / 2) / span / z;
    const nz = z >= 6 ? 1 : z * 1.6;
    emit(cx + ux * (1 - z / nz), cy + uy * (1 - z / nz), nz);
  };

  const strokeW = 2.2 / z;
  const labelSize = 26 / z;

  const palette = ["#22d3ee", "#e879f9", "#fcd34d", "#34d399", "#fb7185"];

  return (
    <div
      ref={hostRef}
      className={"relative h-full w-full overflow-hidden touch-none select-none bg-black/60 ring-1 ring-cyan-400/10 shadow-[inset_0_0_12px_rgba(0,0,0,0.8)] " + (active ? "cursor-grabbing" : "cursor-grab")}
      style={{ minWidth: floor[0] + "rem", minHeight: floor[1] + "rem" }}
      onPointerDown={onDown}
      onPointerMove={onMove}
      onPointerUp={onUp}
      onPointerCancel={onUp}
      onDoubleClick={onDouble}
    >
      <svg className="absolute inset-0 h-full w-full" viewBox={vb} preserveAspectRatio="xMidYMid slice">
        <defs>
          <pattern id={uid + "-grid"} width="50" height="50" patternUnits="userSpaceOnUse">
            <path d="M50 0 L0 0 0 50" fill="none" stroke="rgba(34,211,238,0.14)" strokeWidth={0.9 / z} />
          </pattern>
          <pattern id={uid + "-grid2"} width="250" height="250" patternUnits="userSpaceOnUse">
            <path d="M250 0 L0 0 0 250" fill="none" stroke="rgba(34,211,238,0.28)" strokeWidth={1.4 / z} />
          </pattern>
          <radialGradient id={uid + "-vig"} cx="50%" cy="50%" r="72%">
            <stop offset="55%" stopColor="#000" stopOpacity="0" />
            <stop offset="100%" stopColor="#000" stopOpacity="0.85" />
          </radialGradient>
          <filter id={uid + "-glow"} x="-40%" y="-40%" width="180%" height="180%">
            <feGaussianBlur stdDeviation={5 / z} result="b" />
            <feMerge>
              <feMergeNode in="b" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
          <linearGradient id={uid + "-sweep"} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor="#22d3ee" stopOpacity="0" />
            <stop offset="100%" stopColor="#22d3ee" stopOpacity="0.5" />
          </linearGradient>
        </defs>

        <rect x={-S} y={-S} width={S * 3} height={S * 3} fill="#05070a" />
        <rect x={-S} y={-S} width={S * 3} height={S * 3} fill={"url(#" + uid + "-grid)"} />
        <rect x={-S} y={-S} width={S * 3} height={S * 3} fill={"url(#" + uid + "-grid2)"} />

        {regions.map((r, i) => {
          const col = palette[i % palette.length];
          const isHot = hover === r.id;
          const common = {
            fill: col,
            fillOpacity: isHot ? 0.28 : 0.13,
            stroke: col,
            strokeWidth: isHot ? strokeW * 1.8 : strokeW,
            strokeLinejoin: "round" as const,
            onPointerEnter: () => setHover(r.id),
            onPointerLeave: () => setHover((h) => (h === r.id ? null : h)),
            style: { transition: "fill-opacity 200ms ease-out, stroke-width 200ms ease-out" },
            filter: isHot ? "url(#" + uid + "-glow)" : undefined,
          };
          if (r.path) {
            return (
              <g key={r.id}>
                <path d={r.path} transform={"scale(" + S + ")"} vectorEffect="non-scaling-stroke" {...common} />
              </g>
            );
          }
          const b = r.bounds;
          if (!b) return null;
          return (
            <g key={r.id}>
              <rect x={b.x * S} y={b.y * S} width={b.w * S} height={b.h * S} {...common} />
              <path
                d={
                  "M" + (b.x * S + 6 / z) + "," + (b.y * S + 22 / z) +
                  " L" + (b.x * S + 6 / z) + "," + (b.y * S + 6 / z) +
                  " L" + (b.x * S + 22 / z) + "," + (b.y * S + 6 / z)
                }
                fill="none"
                stroke={col}
                strokeOpacity="0.9"
                strokeWidth={strokeW}
              />
            </g>
          );
        })}

        {regions.map((r, i) => {
          const col = palette[i % palette.length];
          let lx = 0.5;
          let ly = 0.5;
          if (r.bounds) {
            lx = r.bounds.x + r.bounds.w / 2;
            ly = r.bounds.y + r.bounds.h / 2;
          } else if (r.path) {
            const nums = r.path.match(/-?\d*\.?\d+/g);
            if (nums && nums.length >= 2) {
              const xs: number[] = [];
              const ys: number[] = [];
              for (let k = 0; k + 1 < nums.length; k += 2) {
                xs.push(parseFloat(nums[k]));
                ys.push(parseFloat(nums[k + 1]));
              }
              lx = (Math.min(...xs) + Math.max(...xs)) / 2;
              ly = (Math.min(...ys) + Math.max(...ys)) / 2;
            }
          }
          return (
            <text
              key={"lbl-" + r.id}
              x={lx * S}
              y={ly * S}
              textAnchor="middle"
              dominantBaseline="middle"
              fontFamily="ui-monospace, monospace"
              fontWeight="700"
              fontSize={labelSize}
              letterSpacing={labelSize * 0.16}
              fill={hover === r.id ? "#ffffff" : col}
              opacity={hover === r.id ? 1 : 0.85}
              style={{ pointerEvents: "none", transition: "opacity 200ms ease-out" }}
            >
              {(r.label || "").toUpperCase()}
            </text>
          );
        })}

        <g opacity="0.55" style={{ pointerEvents: "none" }}>
          <line x1={cx * S - half} y1={cy * S} x2={cx * S + half} y2={cy * S} stroke="rgba(34,211,238,0.25)" strokeWidth={0.8 / z} strokeDasharray={6 / z + " " + 10 / z} />
          <line x1={cx * S} y1={cy * S - half} x2={cx * S} y2={cy * S + half} stroke="rgba(34,211,238,0.25)" strokeWidth={0.8 / z} strokeDasharray={6 / z + " " + 10 / z} />
          <circle cx={cx * S} cy={cy * S} r={9 / z} fill="none" stroke="#22d3ee" strokeWidth={1.4 / z} />
          <circle cx={cx * S} cy={cy * S} r={2.5 / z} fill="#22d3ee" />
        </g>

        <rect x={cx * S - half} y={cy * S - half} width={half * 2} height={half * 2} fill={"url(#" + uid + "-vig)"} style={{ pointerEvents: "none" }} />
      </svg>

      <div
        className="absolute inset-0 opacity-[0.16] mix-blend-screen"
        style={{
          backgroundImage: "repeating-linear-gradient(0deg, rgba(34,211,238,0.35) 0px, rgba(34,211,238,0.35) 1px, transparent 1px, transparent 3px)",
          pointerEvents: "none",
        }}
      />
      <div
        className="absolute inset-y-0 w-1/3 animate-pulse"
        style={{
          left: "0%",
          background: "linear-gradient(90deg, rgba(34,211,238,0) 0%, rgba(34,211,238,0.07) 70%, rgba(34,211,238,0) 100%)",
          pointerEvents: "none",
        }}
      />

      <div className="absolute inset-0 pointer-events-none">
