            <div className="flex-1 w-[2px] my-2 bg-gradient-to-b from-cyan-400/60 via-fuchsia-500/40 to-transparent" />
            <span className="text-[10px] font-medium uppercase tracking-[0.15em] text-neutral-400">LVL</span>
          </div>

          <div className="flex-1 flex flex-col justify-between border border-cyan-400/25 bg-neutral-900/85 backdrop-blur-md p-3">
            {[
