                }
              >
                <div className="w-full h-full">
                  <StatReadout value={a.v} delta={a.d} tone={selected === a.id ? "accent" : "neutral"}>
                    <span className="flex flex-col items-center leading-tight">
                      <span className="font-bold tracking-widest uppercase">{a.v}</span>
                      <span className="text-[0.55em] tracking-[0.2em] uppercase opacity-70">{a.label}</span>
                    </span>
                  </StatReadout>
                </div>
              </button>
            ))}
          </div>
