export default function GeneratedComponent() {
  // BUDGET height: header 2.25 + pad 0.75 + [search 2 + gap 0.5 + tabs 2.25 + gap 0.5 + list 24.6] + pad 0.75 + footer 1.75 = 35.35 ≤ 38.1
  // BUDGET width: pad 0.75 + left 20 + gap 0.75 + right 29.0 (>= ObjectiveChecklist 9, StatReadout 3×3.5=10.5, ToggleSwitch 4) + pad 0.75 = 51.25 ≤ 52.0

  type Step = { id: string; label: string; done: boolean; optional?: boolean };
  type Quest = {
    id: string;
    label: string;
    subtitle?: string;
    category: string;
    status?: string;
    danger: string;
    brief: string;
    steps: Step[];
    rewards: { k: string; v: string | number }[];
    loc: { x: number; y: number };
  };

  const QUESTS: Quest[] = [
    {
      id: "q1",
      label: "THE HEIST // KONPEKI",
      subtitle: "Dexter DeShawn · Watson",
      category: "main",
      status: "ACTIVE",
      danger: "VERY HIGH",
      brief: "Infiltrate Konpeki Plaza and extract the Relic prototype before Arasaka locks the floor.",
      steps: [
        { id: "s1", label: "Meet T-Bug at the No-Tell Motel", done: true },
        { id: "s2", label: "Check in under the alias", done: true },
        { id: "s3", label: "Plant the shard in the vault terminal", done: false },
        { id: "s4", label: "Scan the penthouse security grid", done: false, optional: true },
        { id: "s5", label: "Exfil via the maintenance shaft", done: false },
      ],
      rewards: [
        { k: "EDDIES", v: "21.5K" },
        { k: "STREET CRED", v: 1400 },
        { k: "XP", v: 3200 },
      ],
      loc: { x: 0.41, y: 0.28 },
    },
    {
      id: "q2",
      label: "CHIPPIN' IN",
      subtitle: "Rogue Amendiares · Afterlife",
      category: "main",
      status: "NEW",
      danger: "HIGH",
      brief: "Track the ghost in the machine. Rogue wants answers about a dead Solo who won't stay dead.",
      steps: [
        { id: "s1", label: "Talk to Rogue at the Afterlife", done: true },
        { id: "s2", label: "Locate the Ebunike docks", done: false },
        { id: "s3", label: "Breach the cargo container net", done: false },
      ],
      rewards: [
        { k: "EDDIES", v: "9.8K" },
        { k: "STREET CRED", v: 860 },
        { k: "XP", v: 1750 },
      ],
      loc: { x: 0.22, y: 0.55 },
    },
    {
      id: "q3",
      label: "HEROES ON THE RUN",
      subtitle: "Padre · Heywood",
      category: "side",
      status: "TRACKED",
      danger: "MEDIUM",
      brief: "Valentinos need a driver and a gun. Padre pays in favors, which spend better than eddies.",
      steps: [
        { id: "s1", label: "Meet the crew at El Coyote Cojo", done: true },
        { id: "s2", label: "Intercept the 6th Street convoy", done: false },
        { id: "s3", label: "Return the cargo intact", done: false, optional: true },
      ],
      rewards: [
        { k: "EDDIES", v: "4.2K" },
        { k: "STREET CRED", v: 420 },
        { k: "XP", v: 900 },
      ],
      loc: { x: 0.63, y: 0.66 },
    },
    {
      id: "q4",
      label: "SINNERMAN'S SIGNAL",
      subtitle: "Wakako Okada · Westbrook",
      category: "side",
      danger: "LOW",
      brief: "A braindance smuggler's signal is bleeding across Japantown. Find the source, kill the feed.",
      steps: [
        { id: "s1", label: "Triangulate the BD relay", done: false },
        { id: "s2", label: "Disable the three repeaters", done: false },
      ],
      rewards: [
        { k: "EDDIES", v: "2.1K" },
        { k: "STREET CRED", v: 210 },
        { k: "XP", v: 480 },
      ],
      loc: { x: 0.74, y: 0.34 },
    },
    {
      id: "q5",
      label: "HUSTLE: CYBERPSYCHO 0x9F",
      subtitle: "NCPD Scanner · Santo Domingo",
      category: "ncpd",
      status: "URGENT",
      danger: "EXTREME",
      brief: "Chrome-burned merc lost containment near the Arroyo overpass. Neutralize, recover the shard.",
      steps: [
        { id: "s1", label: "Sweep the overpass underdeck", done: true },
        { id: "s2", label: "Neutralize the cyberpsycho", done: false },
        { id: "s3", label: "Upload evidence to Regina", done: false },
      ],
      rewards: [
        { k: "EDDIES", v: "5.6K" },
        { k: "STREET CRED", v: 640 },
        { k: "XP", v: 1100 },
      ],
      loc: { x: 0.55, y: 0.81 },
    },
    {
      id: "q6",
      label: "HUSTLE: GUN RUN 14",
      subtitle: "NCPD Scanner · Pacifica",
      category: "ncpd",
      danger: "MEDIUM",
      brief: "Scavs moving military iron through the drowned mall. Shut the pipeline down.",
      steps: [
        { id: "s1", label: "Clear the Grand Imperial atrium", done: false },
        { id: "s2", label: "Seize the weapons crate", done: false },
      ],
      rewards: [
        { k: "EDDIES", v: "3.4K" },
        { k: "STREET CRED", v: 300 },
        { k: "XP", v: 620 },
      ],
      loc: { x: 0.14, y: 0.78 },
    },
  ];

  const [cat, setCat] = useState("all");
  const [query, setQuery] = useState("");
  const [sel, setSel] = useState<string | null>("q1");
  const [tracked, setTracked] = useState<string | null>("q3");
  const [pulse, setPulse] = useState(0);

  useEffect(() => {
    const t = setInterval(() => setPulse((p) => (p + 1) % 100), 90);
    return () => clearInterval(t);
  }, []);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return QUESTS.filter(
      (x) =>
        (cat === "all" || x.category === cat) &&
        (q === "" ||
          x.label.toLowerCase().includes(q) ||
          (x.subtitle || "").toLowerCase().includes(q))
    );
  }, [cat, query]);

  const active = useMemo(
    () => QUESTS.find((x) => x.id === sel) || null,
    [sel]
  );

  const options = useMemo(() => {
    const c = (id: string) =>
      QUESTS.filter((x) => id === "all" || x.category === id).length;
    return [
      { id: "all", label: "ALL", count: c("all") },
      { id: "main", label: "MAIN", count: c("main") },
      { id: "side", label: "GIGS", count: c("side") },
      { id: "ncpd", label: "NCPD", count: c("ncpd") },
    ];
  }, []);

  const listItems = useMemo(
    () =>
      filtered.map((x) => ({
        id: x.id,
        label: (tracked === x.id ? "◈ " : "") + x.label,
        subtitle: x.subtitle,
        category: x.category.toUpperCase(),
        status: tracked === x.id ? "TRACKED" : x.status,
        children: x.id === sel ? x.steps.map((s) => ({ id: s.id, label: s.label, done: s.done })) : undefined,
      })),
    [filtered, sel, tracked]
  );

  const doneCount = active ? active.steps.filter((s) => s.done).length : 0;
  const nextStep = active ? active.steps.find((s) => !s.done) : null;

  return (
    <div className="h-full w-full flex flex-col overflow-hidden rounded-none bg-neutral-950 bg-gradient-to-br from-neutral-950 via-black to-neutral-900 text-cyan-50 font-mono">
      {/* HEADER */}
      <div className="h-9 flex-none px-3 flex items-center justify-between border-b border-cyan-400/25 bg-gradient-to-r from-cyan-500/15 via-neutral-900/80 to-transparent">
        <div className="flex items-center gap-2 min-w-0">
          <span
            className="inline-block h-2 w-2 bg-amber-300 shadow-[0_0_10px_rgba(252,211,77,0.9)]"
            style={{ opacity: pulse % 20 < 10 ? 1 : 0.25 }}
          />
          <span className="text-xs font-bold uppercase tracking-[0.22em] text-cyan-200 truncate">
            QUEST JOURNAL
          </span>
        </div>
        <span className="text-[10px] font-medium uppercase tracking-[0.15em] text-neutral-400 truncate">
          {filtered.length} LOGGED / {tracked ? "TRK " + tracked.toUpperCase() : "NO TRACK"}
        </span>
      </div>

      {/* BODY */}
      <div className="flex-1 flex gap-3 p-3">
        {/* LEFT */}
        <div className="w-[20rem] flex flex-col gap-2">
          <div className="h-[2rem]">
            <SearchInput value={query} onChange={setQuery} placeholder="SEARCH LOG…" />
          </div>
          <div className="h-[2.25rem]">
            <TabSelector options={options} value={cat} onChange={setCat} />
          </div>
          <div className="flex-1">
            <ListSelector
              items={listItems}
              value={sel}
              onChange={setSel}
              onActivate={(id) => setTracked((t) => (t === id ? null : id))}
            />
          </div>
        </div>

        {/* RIGHT */}
        <div className="flex-1 flex flex-col gap-2 border border-cyan-400/25 bg-neutral-900/85 backdrop-blur-md p-3 shadow-[0_0_20px_rgba(34,211,238,0.15)]">
          {active ? (
            <>
              <div className="flex items-start justify-between gap-2">
                <div className="flex-1 min-w-0">
                  <div className="text-lg font-bold uppercase tracking-[0.2em] leading-tight text-cyan-100 truncate">
                    {active.label}
                  </div>
                  <div className="text-[10px] font-medium uppercase tracking-[0.15em] text-neutral-400 truncate">
                    {active.subtitle} · THREAT {active.danger}
                  </div>
                </div>
                <div className="px-2 py-1 border border-fuchsia-400/40 rounded-full bg-neutral-800/70 text-[10px] uppercase tracking-[0.15em] text-fuchsia-300">
                  {active.category}
                </div>
              </div>

              <p className="text-sm leading-relaxed text-cyan-100/90 line-clamp-2">
                {active.brief}
              </p>

              <div className="flex items-center gap-2">
                <div className="flex-1 h-[0.4rem] bg-black/60 border border-cyan-400/20 overflow-clip">
                  <div
                    className="h-full bg-gradient-to-r from-cyan-400 to-cyan-200 shadow-[0_0_8px_rgba(34,211,238,0.6)] transition-all duration-500 ease-out"
                    style={{ width: (doneCount / active.steps.length) * 100 + "%" }}
                  />
                </div>
                <span className="text-[10px] uppercase tracking-[0.15em] text-amber-300/80">
                  {doneCount}/{active.steps.length}
                </span>
              </div>

              <div className="flex-1 bg-black/60 ring-1 ring-cyan-400/10 shadow-[inset_0_0_12px_rgba(0,0,0,0.8)] p-2">
                <ObjectiveChecklist
                  steps={active.steps}
                  activeId={nextStep ? nextStep.id : null}
                />
              </div>

              <div className="flex gap-2">
                {active.rewards.map((r) => (
                  <div key={r.k} className="flex-1 flex flex-col gap-1">
                    <div className="h-[2.4rem]">
                      <StatReadout
                        value={r.v}
                        tone={r.k === "EDDIES" ? "accent" : "neutral"}
                      >
                        <span className="font-bold tracking-widest">{r.v}</span>
                      </StatReadout>
                    </div>
                    <span className="text-[10px] font-medium uppercase tracking-[0.15em] text-neutral-400 text-center truncate">
                      {r.k}
                    </span>
                  </div>
                ))}
              </div>

              <div className="flex items-center justify-between gap-3 border-t border-cyan-400/20 pt-2">
                <div className="flex-1 min-w-0">
                  <div className="text-xs font-semibold uppercase tracking-[0.18em] leading-none text-cyan-300/80">
                    TRACK QUEST
                  </div>
                  <div className="text-[10px] uppercase tracking-[0.15em] text-neutral-400 truncate mt-1">
                    PIN [{active.loc.x.toFixed(2)}, {active.loc.y.toFixed(2)}] TO MAP
                  </div>
                </div>
                <div className="w-[4.5rem] h-[2rem]">
                  <ToggleSwitch
                    on={tracked === active.id}
                    onChange={(on) => setTracked(on ? active.id : null)}
                  />
                </div>
              </div>
            </>
          ) : (
            <div className="flex-1 flex items-center justify-center text-[10px] uppercase tracking-[0.2em] text-neutral-500">
              NO ENTRY SELECTED
            </div>
          )}
        </div>
      </div>

      {/* FOOTER */}
      <div className="h-7 flex-none px-3 flex items-center justify-between border-t border-cyan-400/20 bg-black/70">
        <span className="text-[10px] font-medium uppercase tracking-[0.15em] text-amber-300/70 truncate">
          NETWATCH LINK // STABLE
        </span>
        <span className="text-[10px] font-medium uppercase tracking-[0.15em] text-neutral-400 truncate">
          {tracked ? "ROUTE BROADCAST → NIGHT CITY MAP" : "AWAITING TRACK CMD"}
        </span>
      </div>
    </div>
  );
}

