export default function GeneratedComponent() {
  // BUDGET height: header 2.25 + pad 0.75 + [tabs 2.25 + gap 0.5 + grid 26.6] + pad 0.75 + footer 1.75 = 34.85... body flex fills 38.1
  // BUDGET width: pad 0.5 + slots 11 + gap 0.75 + center 24.5 + gap 0.75 + details 13.5 + pad 0.5 = 51.5 ≤ 52.0

  type Item = {
    id: string;
    label: string;
    icon?: string;
    rarity?: string;
    quantity?: number;
    description?: string;
    kind: string;
    cat: string;
    stats?: { label: string; value: number | string }[];
  };

  const ALL_ITEMS: Item[] = [
    { id: "i1", label: "Malorian 3516", icon: "▲", rarity: "legendary", quantity: 1, kind: "weapon", cat: "weapons", description: "Johnny's iconic hand cannon. Burns through chrome.", stats: [{ label: "DMG", value: 184 }, { label: "RPM", value: 62 }, { label: "CRIT", value: "+31%" }] },
    { id: "i2", label: "Yinglong SMG", icon: "◆", rarity: "epic", quantity: 1, kind: "weapon", cat: "weapons", description: "Smart-linked submachine gun, Arasaka issue.", stats: [{ label: "DMG", value: 96 }, { label: "RPM", value: 720 }] },
    { id: "i3", label: "Mantis Blades", icon: "✚", rarity: "rare", quantity: 1, kind: "weapon", cat: "weapons", description: "Retractable monomolecular arm blades.", stats: [{ label: "DMG", value: 121 }, { label: "BLEED", value: "+40%" }] },
    { id: "i4", label: "Netrunner Suit", icon: "■", rarity: "epic", quantity: 1, kind: "torso", cat: "clothing", description: "Thermal-weave bodysuit with ICE shielding.", stats: [{ label: "ARMOR", value: 214 }, { label: "RAM", value: "+3" }] },
    { id: "i5", label: "Samurai Jacket", icon: "▮", rarity: "legendary", quantity: 1, kind: "torso", cat: "clothing", description: "Wake the f**k up. Smells like 2023.", stats: [{ label: "ARMOR", value: 188 }, { label: "COOL", value: "+2" }] },
    { id: "i6", label: "Kabuki Optics", icon: "◉", rarity: "rare", quantity: 1, kind: "head", cat: "clothing", description: "Street-market AR visor, cracked bezel.", stats: [{ label: "ARMOR", value: 74 }] },
    { id: "i7", label: "Militech Boots", icon: "▼", rarity: "uncommon", quantity: 1, kind: "legs", cat: "clothing", description: "Reinforced plating. Heavy, loud, effective.", stats: [{ label: "ARMOR", value: 91 }] },
    { id: "i8", label: "Tetratronic Mk.4", icon: "⬢", rarity: "legendary", quantity: 1, kind: "deck", cat: "cyberware", description: "Top-tier cyberdeck. Overclock without the melt.", stats: [{ label: "RAM", value: 14 }, { label: "BUFFER", value: 9 }] },
    { id: "i9", label: "Biodyne Berserk", icon: "⬣", rarity: "epic", quantity: 1, kind: "deck", cat: "cyberware", description: "Adrenal override operating system.", stats: [{ label: "RAM", value: 9 }, { label: "DMG", value: "+18%" }] },
    { id: "i10", label: "Kiroshi Optics", icon: "◎", rarity: "rare", quantity: 1, kind: "head", cat: "cyberware", description: "Threat-tagging ocular implant.", stats: [{ label: "SCAN", value: "+2" }] },
    { id: "i11", label: "MaxDoc Mk.3", icon: "✛", rarity: "uncommon", quantity: 7, kind: "consumable", cat: "consumables", description: "Instant heal injector, mild nausea.", stats: [{ label: "HEAL", value: "60%" }] },
    { id: "i12", label: "Bounce Back", icon: "✢", rarity: "common", quantity: 12, kind: "consumable", cat: "consumables", description: "Regenerative drip over 10 seconds.", stats: [{ label: "HEAL", value: "35%" }] },
  ];

  const SLOTS = [
    { id: "head", label: "HEAD", accepts: "head" },
    { id: "torso", label: "TORSO", accepts: "torso" },
    { id: "legs", label: "LEGS", accepts: "legs" },
    { id: "weapon", label: "WPN-1", accepts: "weapon" },
    { id: "weapon2", label: "WPN-2", accepts: "weapon" },
    { id: "deck", label: "DECK", accepts: "deck" },
  ];

  const [equipped, setEquipped] = useState<Record<string, string | null>>({
    head: "i6", torso: "i5", legs: null, weapon: "i1", weapon2: null, deck: "i8",
  });
  const [tab, setTab] = useState("all");
  const [query, setQuery] = useState("");
  const [sel, setSel] = useState<string | null>("i1");
  const [flash, setFlash] = useState<string>("LINK STABLE // HUD SYNC OK");

  const equippedIds = useMemo(() => new Set(Object.values(equipped).filter(Boolean) as string[]), [equipped]);

  const tabs = useMemo(() => {
    const c = (k: string) => ALL_ITEMS.filter((i) => k === "all" || i.cat === k).length;
    return [
      { id: "all", label: "ALL", count: c("all") },
      { id: "weapons", label: "WPN", count: c("weapons") },
      { id: "clothing", label: "CLOTH", count: c("clothing") },
      { id: "cyberware", label: "CHROME", count: c("cyberware") },
      { id: "consumables", label: "CONSUM", count: c("consumables") },
    ];
  }, []);

  const visible = useMemo(() => {
    const q = query.trim().toLowerCase();
    return ALL_ITEMS.filter((i) => (tab === "all" || i.cat === tab) && (!q || i.label.toLowerCase().includes(q)))
      .map((i) => ({ ...i, equipped: equippedIds.has(i.id) }));
  }, [tab, query, equippedIds]);

  const selItem = useMemo(() => ALL_ITEMS.find((i) => i.id === sel) || null, [sel]);
  const selSlot = useMemo(() => {
    if (!selItem) return null;
    const own = SLOTS.find((s) => equipped[s.id] === selItem.id);
    if (own) return own;
    return SLOTS.find((s) => s.accepts === selItem.kind && !equipped[s.id]) || SLOTS.find((s) => s.accepts === selItem.kind) || null;
  }, [selItem, equipped]);

  const isEquipped = !!(selItem && equippedIds.has(selItem.id));

  const equip = useCallback(() => {
    if (!selItem || !selSlot) return;
    setEquipped((e) => ({ ...e, [selSlot.id]: selItem.id }));
    setFlash("EQUIP → " + selSlot.label + " // PUSHING MODS TO HUD");
  }, [selItem, selSlot]);

  const unequip = useCallback(() => {
    if (!selItem) return;
    setEquipped((e) => {
      const n = { ...e };
      Object.keys(n).forEach((k) => { if (n[k] === selItem.id) n[k] = null; });
      return n;
    });
    setFlash("UNEQUIP // STAT DELTA REVERTED");
  }, [selItem]);

  const armor = useMemo(() => {
    let a = 0;
    Object.values(equipped).forEach((id) => {
      const it = ALL_ITEMS.find((x) => x.id === id);
      const st = it?.stats?.find((s) => s.label === "ARMOR");
      if (st) a += Number(st.value) || 0;
    });
    return a;
  }, [equipped]);

  const dmg = useMemo(() => {
    const it = ALL_ITEMS.find((x) => x.id === equipped.weapon);
    const st = it?.stats?.find((s) => s.label === "DMG");
    return st ? Number(st.value) || 0 : 0;
  }, [equipped]);

  return (
    <div className="h-full w-full flex flex-col overflow-hidden rounded-none bg-neutral-950 bg-gradient-to-br from-neutral-950 via-black to-neutral-900 text-cyan-50 font-mono">
      {/* header */}
      <div className="flex-none h-9 px-3 flex items-center justify-between border-b border-cyan-400/25 bg-gradient-to-r from-cyan-500/15 via-neutral-900/80 to-transparent">
        <div className="flex items-center gap-2 min-w-0">
          <span className="h-2 w-2 bg-cyan-400 animate-pulse shadow-[0_0_12px_rgba(34,211,238,0.9)]" />
          <span className="text-xs font-bold uppercase tracking-[0.22em] text-cyan-200 truncate">LOADOUT // INVENTORY.SYS</span>
        </div>
        <span className="text-[10px] font-medium uppercase tracking-[0.15em] text-fuchsia-400/80 truncate">V // NIGHT CITY</span>
      </div>

      {/* body */}
      <div className="flex-1 flex gap-3 p-2 relative">
        <div className="pointer-events-none absolute inset-0 opacity-[0.07] bg-[repeating-linear-gradient(0deg,transparent_0px,transparent_2px,rgba(34,211,238,0.9)_3px)]" />

        {/* equipment slots */}
        <div className="w-[11.5rem] flex flex-col gap-2">
          <div className="flex-none text-xs font-semibold uppercase tracking-[0.18em] leading-none text-cyan-300/80">LOADOUT</div>
          <div className="flex-1 grid grid-cols-2 grid-rows-3 gap-2">
            {SLOTS.map((s) => {
              const it = equipped[s.id] ? ALL_ITEMS.find((x) => x.id === equipped[s.id])! : null;
              return (
                <div key={s.id} className="flex flex-col gap-1">
                  <span className="text-[10px] font-medium uppercase tracking-[0.15em] leading-tight text-neutral-400">{s.label}</span>
                  <div className="flex-1">
                    <EquipmentSlot
                      slotId={s.id}
                      accepts={s.accepts}
                      item={it ? { id: it.id, label: it.label, icon: it.icon, rarity: it.rarity } : null}
                      onSelect={(id) => { const cur = equipped[id]; if (cur) setSel(cur); }}
                      onClear={(id) => { setEquipped((e) => ({ ...e, [id]: null })); setFlash("SLOT " + id.toUpperCase() + " CLEARED"); }}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* center: tabs + search + grid */}
        <div className="flex-1 flex flex-col gap-2">
          <div className="flex-none h-[2.25rem] flex gap-2">
            <div className="flex-1"><TabSelector options={tabs} value={tab} onChange={setTab} /></div>
            <div className="w-[9rem]"><SearchInput value={query} onChange={setQuery} placeholder="SEARCH GEAR" /></div>
          </div>
          <div className="flex-1">
            <ItemGrid
              items={visible}
              value={sel}
              onChange={(id) => setSel(id)}
              onActivate={(id) => {
                const it = ALL_ITEMS.find((x) => x.id === id);
                if (!it) return;
                setSel(id);
                if (equippedIds.has(id)) {
                  setEquipped((e) => { const n = { ...e }; Object.keys(n).forEach((k) => { if (n[k] === id) n[k] = null; }); return n; });
                  setFlash("UNEQUIP // " + it.label.toUpperCase());
                } else {
                  const slot = SLOTS.find((s) => s.accepts === it.kind && !equipped[s.id]) || SLOTS.find((s) => s.accepts === it.kind);
                  if (slot) { setEquipped((e) => ({ ...e, [slot.id]: id })); setFlash("EQUIP → " + slot.label + " // HUD SYNC"); }
                  else setFlash("NO COMPATIBLE SLOT");
                }
              }}
            />
          </div>
        </div>

        {/* details + actions */}
        <div className="w-[14rem] flex flex-col gap-2">
          <div className="flex-1">
            <ItemDetails item={selItem ? { id: selItem.id, label: selItem.label, description: selItem.description, rarity: selItem.rarity, stats: selItem.stats } : null} />
          </div>
          <div className="flex-none h-[2.5rem] flex gap-2">
            <div className="flex-1">
              <ActionButton onPress={equip} tone="accent" disabled={!selItem || isEquipped || !selSlot}>
                <span className="font-bold tracking-widest uppercase">EQUIP</span>
              </ActionButton>
            </div>
            <div className="flex-1">
              <ActionButton onPress={unequip} tone="danger" disabled={!isEquipped}>
                <span className="font-bold tracking-widest uppercase">UNEQUIP</span>
              </ActionButton>
            </div>
          </div>
        </div>
      </div>

      {/* footer */}
      <div className="flex-none h-7 px-3 flex items-center justify-between gap-3 border-t border-cyan-400/20 bg-black/70">
        <span className="text-[10px] font-medium uppercase tracking-[0.15em] leading-tight text-amber-300/70 truncate">{flash}</span>
        <span className="text-[10px] font-medium uppercase tracking-[0.15em] leading-tight text-cyan-300/80 truncate">ARMOR {armor} // DMG {dmg}</span>
      </div>
    </div>
  );
}

